import React, { useState, useEffect } from 'react';
import {
  X,
  Wallet,
  Plus,
  ArrowUpRight,
  AlertTriangle,
  Users,
  RefreshCw,
  Eye,
  Search,
  CreditCard,
} from 'lucide-react';

import { DisbursementWallet, DisbursementRequest, ChatUser } from '@etaxwala/types';
import { useAuthStore } from '@/store/auth-store';

interface AdminFloatDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  staffDirectory: ChatUser[];
  isAdminUser: boolean;
}

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

export const AdminFloatDrawer: React.FC<AdminFloatDrawerProps> = ({
  isOpen,
  onClose,
  staffDirectory,
  isAdminUser,
}) => {
  const { staffToken } = useAuthStore();
  const [wallet, setWallet] = useState<DisbursementWallet | null>(null);
  const [requests, setRequests] = useState<DisbursementRequest[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'requests' | 'topups'>('requests');
  const [filterStatus, setFilterStatus] = useState<'ALL' | 'PENDING' | 'PAID' | 'REJECTED'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  // Top Up Modal State
  const [showTopupModal, setShowTopupModal] = useState(false);
  const [topupAmount, setTopupAmount] = useState('');
  const [topupMode, setTopupMode] = useState('BANK_TRANSFER');
  const [topupRef, setTopupRef] = useState('');
  const [topupNotes, setTopupNotes] = useState('');
  const [topupSubmitting, setTopupSubmitting] = useState(false);

  // Assign Officer Modal State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [selectedOfficerId, setSelectedOfficerId] = useState<number | ''>('');
  const [initialBalance, setInitialBalance] = useState('0');
  const [assignSubmitting, setAssignSubmitting] = useState(false);

  // Proof lightbox
  const [previewProofUrl, setPreviewProofUrl] = useState<string | null>(null);

  const authHeaders = {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${staffToken}`,
  };

  const loadData = async () => {
    setLoading(true);
    try {
      const [walletRes, requestsRes] = await Promise.all([
        fetch(`${API_BASE}/v1/disbursements/wallet`, { headers: authHeaders }),
        fetch(`${API_BASE}/v1/disbursements/requests?limit=100`, { headers: authHeaders }),
      ]);

      const [walletJson, requestsJson] = await Promise.all([walletRes.json(), requestsRes.json()]);

      if (walletJson.success) setWallet(walletJson.data);
      if (requestsJson.success && Array.isArray(requestsJson.data)) {
        setRequests(requestsJson.data);
      }
    } catch (err) {
      console.error('Failed to load float data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isOpen && staffToken) {
      loadData();
    }
  }, [isOpen, staffToken, loadData]);

  if (!isOpen) return null;

  const handleTopupSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const parsed = parseFloat(topupAmount);
    if (isNaN(parsed) || parsed <= 0) return;

    setTopupSubmitting(true);
    try {
      const res = await fetch(`${API_BASE}/v1/disbursements/topup`, {
        method: 'POST',
        headers: authHeaders,
        body: JSON.stringify({
          amount: parsed,
          paymentMode: topupMode,
          referenceNo: topupRef,
          notes: topupNotes,
        }),
      });
      const data = await res.json();
      if (data.success) {
        setShowTopupModal(false);
        setTopupAmount('');
        setTopupRef('');
        setTopupNotes('');
        await loadData();
      } else {
        alert(data.error || 'Failed to top up float.');
      }
    } catch (err: any) {
      alert(err.message || 'Error executing top up.');
    } finally {
      setTopupSubmitting(false);
    }
  };

  const handleAssignOfficerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedOfficerId) return;

    setAssignSubmitting(true);
    try {
      const res = await fetch(`${API_BASE}/v1/disbursements/assign-officer`, {
        method: 'POST',
        headers: authHeaders,
        body: JSON.stringify({
          officerId: selectedOfficerId,
          initialBalance: parseFloat(initialBalance) || 0,
        }),
      });
      const data = await res.json();
      if (data.success) {
        setShowAssignModal(false);
        await loadData();
      } else {
        alert(data.error || 'Failed to assign officer.');
      }
    } catch (err: any) {
      alert(err.message || 'Error assigning officer.');
    } finally {
      setAssignSubmitting(false);
    }
  };

  const filteredRequests = requests.filter((r) => {
    const matchesStatus = filterStatus === 'ALL' || r.status === filterStatus;
    const q = searchQuery.toLowerCase().trim();
    const matchesSearch =
      !q ||
      r.requestCode.toLowerCase().includes(q) ||
      (r.requesterName && r.requesterName.toLowerCase().includes(q)) ||
      (r.clientRef && r.clientRef.toLowerCase().includes(q)) ||
      r.purposeCategory.toLowerCase().includes(q);
    return matchesStatus && matchesSearch;
  });

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex justify-end">
      <div className="bg-[#FFFDF9] w-full max-w-2xl h-full border-l border-[#EAE6DD] shadow-2xl flex flex-col animate-in slide-in-from-right duration-200 text-slate-800 text-xs">
        {/* Signature ETaxwala Multicolor Top Accent Bar */}
        <div className="h-1.5 w-full bg-gradient-to-r from-[#0084D1] via-[#7C3AED] via-[#E11D48] to-[#F97316] shrink-0" />

        {/* Top Header */}
        <div className="px-6 py-4 bg-[#1B365D] text-white flex items-center justify-between shrink-0 shadow-md">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-white/10 backdrop-blur-md flex items-center justify-center border border-white/20">
              <Wallet className="w-5 h-5 text-amber-300" />
            </div>
            <div>
              <h2 className="text-base font-black text-white flex items-center gap-2">
                Accounts Float & Disbursement Tracker
                <span className="text-[10px] font-bold px-2 py-0.2 rounded-full bg-purple-500/30 text-purple-200 border border-purple-400/30">
                  Admin Only
                </span>
              </h2>
              <p className="text-xs text-white/75">
                Real-time operational float balance, top-up logs & payment audit
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={loadData}
              className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-white transition-colors"
              title="Refresh Data"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            </button>
            <button
              type="button"
              onClick={onClose}
              className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-white transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Float Balance Banner */}
        <div className="p-6 bg-gradient-to-b from-[#1B365D]/5 via-white to-white border-b border-[#EAE6DD] space-y-4 shrink-0">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Current Balance Card */}
            <div className="p-4 bg-white border border-[#EAE6DD] rounded-2xl shadow-xs space-y-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block">
                Current Float Balance
              </span>
              <div
                className={`text-2xl font-black ${wallet?.isLowBalance ? 'text-rose-600' : 'text-[#1B365D]'}`}
              >
                Γé╣
                {wallet
                  ? Number(wallet.balance).toLocaleString('en-IN', { minimumFractionDigits: 2 })
                  : '0.00'}
              </div>
              {wallet?.isLowBalance ? (
                <span className="inline-flex items-center gap-1 text-[10px] font-bold text-rose-700 bg-rose-100 px-2 py-0.5 rounded-full">
                  <AlertTriangle className="w-3 h-3" /> Low Balance Alert (&lt; Γé╣5k)
                </span>
              ) : (
                <span className="text-[10px] text-emerald-600 font-bold block">
                  Float Balance Active
                </span>
              )}
            </div>

            {/* Total Funded */}
            <div className="p-4 bg-white border border-[#EAE6DD] rounded-2xl shadow-xs space-y-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block">
                Total Company Funded
              </span>
              <div className="text-xl font-black text-slate-700">
                Γé╣
                {wallet
                  ? Number(wallet.totalFunded).toLocaleString('en-IN', { minimumFractionDigits: 2 })
                  : '0.00'}
              </div>
              <p className="text-[10px] text-slate-400">All top-ups recorded</p>
            </div>

            {/* Total Disbursed */}
            <div className="p-4 bg-white border border-[#EAE6DD] rounded-2xl shadow-xs space-y-1">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block">
                Total Paid to Staff
              </span>
              <div className="text-xl font-black text-emerald-700">
                Γé╣
                {wallet
                  ? Number(wallet.totalDisbursed).toLocaleString('en-IN', {
                      minimumFractionDigits: 2,
                    })
                  : '0.00'}
              </div>
              <p className="text-[10px] text-slate-400">Verified with receipt proofs</p>
            </div>
          </div>

          {/* Officer Profile & Admin Action Buttons */}
          <div className="flex flex-wrap items-center justify-between gap-3 p-3.5 bg-slate-50 border border-slate-200/80 rounded-2xl">
            <div className="flex items-center gap-2.5">
              <div className="w-9 h-9 rounded-xl bg-[#1B365D] text-white font-bold flex items-center justify-center text-xs shadow-2xs">
                {wallet?.officerName?.charAt(0).toUpperCase() || 'A'}
              </div>
              <div>
                <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block">
                  Designated Accounts Officer
                </span>
                <p className="text-xs font-bold text-slate-800">
                  {wallet?.officerName || 'No Accounts Officer Assigned'}
                </p>
                <p className="text-[10px] text-slate-500">{wallet?.officerEmail || ''}</p>
              </div>
            </div>

            {/* Admin Controls */}
            {isAdminUser && (
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => setShowAssignModal(true)}
                  className="px-3 py-1.5 rounded-xl border border-slate-300 hover:bg-white text-slate-700 font-bold text-[11px] transition-all flex items-center gap-1"
                >
                  <Users className="w-3.5 h-3.5" />
                  Change Officer
                </button>
                <button
                  type="button"
                  onClick={() => setShowTopupModal(true)}
                  className="px-4 py-1.5 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-700 hover:to-teal-800 text-white font-bold text-xs shadow-xs transition-all flex items-center gap-1.5"
                >
                  <Plus className="w-3.5 h-3.5" />
                  Top Up Float
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="px-6 py-2.5 bg-white border-b border-[#EAE6DD] flex items-center justify-between shrink-0">
          <div className="flex bg-[#FAF9F5] p-0.5 rounded-xl border border-[#EAE6DD]">
            <button
              type="button"
              onClick={() => setActiveTab('requests')}
              className={`px-3 py-1 rounded-lg font-bold transition-all ${
                activeTab === 'requests'
                  ? 'bg-[#1B365D] text-white shadow-xs'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              Money Requests ({requests.length})
            </button>
            <button
              type="button"
              onClick={() => setActiveTab('topups')}
              className={`px-3 py-1 rounded-lg font-bold transition-all ${
                activeTab === 'topups'
                  ? 'bg-[#1B365D] text-white shadow-xs'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              Top-up History ({wallet?.recentTopups?.length || 0})
            </button>
          </div>

          {activeTab === 'requests' && (
            <div className="flex items-center gap-1.5">
              {(['ALL', 'PENDING', 'PAID', 'REJECTED'] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setFilterStatus(s)}
                  className={`px-2 py-0.5 rounded-md text-[10px] font-bold border transition-all ${
                    filterStatus === s
                      ? 'bg-[#1B365D] text-white border-[#1B365D]'
                      : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-3">
          {activeTab === 'requests' ? (
            <>
              {/* Search Bar */}
              <div className="relative mb-2">
                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search by code, staff name, client reference..."
                  className="w-full pl-9 pr-3 py-2 bg-white border border-[#EAE6DD] rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-none focus:border-[#7C3AED]"
                />
              </div>

              {filteredRequests.length === 0 ? (
                <div className="text-center py-16 space-y-2">
                  <CreditCard className="w-10 h-10 mx-auto text-slate-300" />
                  <p className="font-bold text-slate-700 text-sm">No payment requests found</p>
                  <p className="text-slate-400 text-xs">
                    Staff requests submitted from chat will appear here for audit and fulfillment.
                  </p>
                </div>
              ) : (
                filteredRequests.map((r) => {
                  const isPaid = r.status === 'PAID';
                  const isRejected = r.status === 'REJECTED';

                  return (
                    <div
                      key={r.id}
                      className="p-4 bg-white border border-[#EAE6DD] rounded-2xl shadow-xs space-y-2.5 hover:border-slate-300 transition-all"
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <span className="font-mono font-bold text-xs text-[#1B365D]">
                            #{r.requestCode}
                          </span>
                          <span
                            className={`px-2 py-0.5 rounded-full text-[9px] font-bold border ${
                              isPaid
                                ? 'bg-emerald-50 text-emerald-700 border-emerald-200'
                                : isRejected
                                  ? 'bg-rose-50 text-rose-700 border-rose-200'
                                  : 'bg-amber-50 text-amber-700 border-amber-200'
                            }`}
                          >
                            {r.status}
                          </span>
                        </div>
                        <span className="text-[10px] text-slate-400">
                          {new Date(r.createdAt).toLocaleString([], {
                            dateStyle: 'short',
                            timeStyle: 'short',
                          })}
                        </span>
                      </div>

                      <div className="flex items-baseline justify-between">
                        <div>
                          <span className="text-base font-black text-[#1B365D]">
                            Γé╣
                            {Number(r.amount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                          </span>
                          <span className="ml-2 text-[11px] text-slate-500 font-medium">
                            ΓÇó {r.purposeCategory}
                          </span>
                        </div>
                        <span className="text-[11px] font-bold text-slate-700">
                          By {r.requesterName}
                        </span>
                      </div>

                      {r.clientRef && (
                        <p className="text-[11px] text-slate-500 truncate">
                          Client Ref:{' '}
                          <span className="font-semibold text-slate-700">{r.clientRef}</span>
                        </p>
                      )}

                      <p className="text-[11px] text-slate-600 bg-slate-50 p-2 rounded-lg leading-relaxed">
                        {r.purposeDescription}
                      </p>

                      {/* Payment Destination / Proof */}
                      <div className="flex flex-wrap items-center justify-between gap-2 pt-1 border-t border-slate-100 text-[11px]">
                        <div className="flex items-center gap-2">
                          {r.upiId && (
                            <span className="font-mono text-slate-600">
                              UPI: <b>{r.upiId}</b>
                            </span>
                          )}
                          {r.qrCodeUrl && (
                            <a
                              href={`${API_BASE}${r.qrCodeUrl}`}
                              target="_blank"
                              rel="noreferrer"
                              className="text-[#0084D1] font-bold hover:underline"
                            >
                              [View Requested QR]
                            </a>
                          )}
                        </div>

                        {isPaid && r.paymentProofUrl && (
                          <button
                            type="button"
                            onClick={() => setPreviewProofUrl(`${API_BASE}${r.paymentProofUrl}`)}
                            className="px-2.5 py-1 rounded-lg bg-emerald-50 text-emerald-700 hover:bg-emerald-100 font-bold flex items-center gap-1 border border-emerald-200"
                          >
                            <Eye className="w-3 h-3" /> View Paid Proof Receipt
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })
              )}
            </>
          ) : (
            /* Top-ups History Tab */
            <div className="space-y-3">
              {wallet?.recentTopups && wallet.recentTopups.length > 0 ? (
                wallet.recentTopups.map((t) => (
                  <div
                    key={t.id}
                    className="p-4 bg-white border border-[#EAE6DD] rounded-2xl shadow-xs flex items-center justify-between"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-9 h-9 rounded-xl bg-emerald-50 text-emerald-700 border border-emerald-200 flex items-center justify-center font-bold">
                        <ArrowUpRight className="w-5 h-5" />
                      </div>
                      <div>
                        <div className="text-sm font-black text-emerald-700">
                          +Γé╣{Number(t.amount).toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                        </div>
                        <p className="text-[10px] text-slate-500">
                          Deposited by {t.adminName} via {t.paymentMode}
                          {t.referenceNo ? ` (${t.referenceNo})` : ''}
                        </p>
                        {t.notes && (
                          <p className="text-[10px] text-slate-400 italic mt-0.5">{t.notes}</p>
                        )}
                      </div>
                    </div>
                    <span className="text-[10px] text-slate-400">
                      {new Date(t.createdAt).toLocaleString([], {
                        dateStyle: 'short',
                        timeStyle: 'short',
                      })}
                    </span>
                  </div>
                ))
              ) : (
                <div className="text-center py-16 text-slate-400">No top-ups recorded yet.</div>
              )}
            </div>
          )}
        </div>

        {/* Top Up Modal */}
        {showTopupModal && (
          <div className="fixed inset-0 z-60 bg-slate-950/60 backdrop-blur-xs flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl max-w-md w-full shadow-2xl border border-[#EAE6DD] overflow-hidden animate-in fade-in zoom-in-95 flex flex-col">
              {/* Signature ETaxwala Multicolor Top Accent Bar */}
              <div className="h-1.5 w-full bg-gradient-to-r from-[#0084D1] via-[#7C3AED] via-[#E11D48] to-[#F97316] shrink-0" />

              <div className="p-6 space-y-4">
                <div className="flex items-center justify-between border-b border-[#EAE6DD] pb-3">
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-xl bg-emerald-50 text-emerald-700 flex items-center justify-center font-bold">
                      <Plus className="w-5 h-5" />
                    </div>
                    <div>
                      <h3 className="text-base font-extrabold text-[#1B365D]">
                        Top Up Accounts Float
                      </h3>
                      <p className="text-xs text-slate-500 font-medium">
                        Deposit funds into the Accounts Officer's balance
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => setShowTopupModal(false)}
                    className="w-7 h-7 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-400 hover:text-slate-700 transition-colors flex items-center justify-center cursor-pointer"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>

                <form onSubmit={handleTopupSubmit} className="space-y-3.5">
                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Deposit Amount (Γé╣) <span className="text-rose-500">*</span>
                    </label>
                    <input
                      type="number"
                      step="0.01"
                      min="1"
                      value={topupAmount}
                      onChange={(e) => setTopupAmount(e.target.value)}
                      placeholder="e.g. 20000"
                      required
                      className="w-full px-3.5 py-2.5 bg-white border border-[#EAE6DD] hover:border-[#0084D1]/40 focus:border-[#0084D1] focus:ring-4 focus:ring-[#0084D1]/10 rounded-xl font-black text-lg text-[#1B365D] shadow-2xs transition-all outline-none"
                    />
                    {/* Preset quick buttons */}
                    <div className="flex gap-2 mt-2">
                      {[5000, 10000, 25000, 50000].map((val) => (
                        <button
                          key={val}
                          type="button"
                          onClick={() => setTopupAmount(val.toString())}
                          className="flex-1 py-1.5 text-[11px] font-bold rounded-xl bg-slate-100 hover:bg-blue-50 hover:text-[#0084D1] text-slate-700 border border-slate-200/60 transition-all cursor-pointer"
                        >
                          +Γé╣{(val / 1000).toFixed(0)}k
                        </button>
                      ))}
                    </div>
                  </div>

                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Transfer Mode
                    </label>
                    <select
                      value={topupMode}
                      onChange={(e) => setTopupMode(e.target.value)}
                      className="w-full px-3 py-2 bg-white border border-[#EAE6DD] rounded-xl text-xs font-semibold text-slate-800 focus:border-[#0084D1] focus:ring-2 focus:ring-[#0084D1]/10 outline-none"
                    >
                      <option value="BANK_TRANSFER">Bank IMPS / NEFT Transfer</option>
                      <option value="UPI">Direct UPI Transfer</option>
                      <option value="CASH">Cash Deposit</option>
                      <option value="COMPANY_CARD">Company Credit/Debit Card</option>
                    </select>
                  </div>

                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Bank Reference / UTR #
                    </label>
                    <input
                      type="text"
                      value={topupRef}
                      onChange={(e) => setTopupRef(e.target.value)}
                      placeholder="e.g. UTR-91823901"
                      className="w-full px-3.5 py-2 bg-white border border-[#EAE6DD] rounded-xl font-mono text-xs text-[#1B365D] focus:border-[#0084D1] outline-none"
                    />
                  </div>

                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Notes / Remarks
                    </label>
                    <input
                      type="text"
                      value={topupNotes}
                      onChange={(e) => setTopupNotes(e.target.value)}
                      placeholder="e.g. Weekly operational replenishment"
                      className="w-full px-3.5 py-2 bg-white border border-[#EAE6DD] rounded-xl text-xs text-slate-800 focus:border-[#0084D1] outline-none"
                    />
                  </div>

                  <div className="pt-2 flex justify-end gap-2 border-t border-[#EAE6DD]">
                    <button
                      type="button"
                      onClick={() => setShowTopupModal(false)}
                      className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs transition-all cursor-pointer"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={topupSubmitting}
                      className="px-5 py-2 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-700 hover:to-teal-800 text-white font-extrabold text-xs shadow-md shadow-emerald-900/15 disabled:opacity-50 transition-all cursor-pointer"
                    >
                      {topupSubmitting ? 'Depositing...' : 'Confirm Deposit'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        )}

        {/* Assign Officer Modal */}
        {showAssignModal && (
          <div className="fixed inset-0 z-60 bg-slate-950/60 backdrop-blur-xs flex items-center justify-center p-4">
            <div className="bg-white rounded-3xl max-w-md w-full shadow-2xl border border-[#EAE6DD] overflow-hidden animate-in fade-in zoom-in-95 flex flex-col">
              {/* Signature ETaxwala Multicolor Top Accent Bar */}
              <div className="h-1.5 w-full bg-gradient-to-r from-[#0084D1] via-[#7C3AED] via-[#E11D48] to-[#F97316] shrink-0" />

              <div className="p-6 space-y-4">
                <div className="flex items-center justify-between border-b border-[#EAE6DD] pb-3">
                  <div className="flex items-center gap-2.5">
                    <div className="w-9 h-9 rounded-xl bg-purple-50 text-[#7C3AED] flex items-center justify-center font-bold">
                      <Users className="w-5 h-5" />
                    </div>
                    <div>
                      <h3 className="text-base font-extrabold text-[#1B365D]">
                        Assign Accounts Officer
                      </h3>
                      <p className="text-xs text-slate-500 font-medium">
                        Designate which staff member holds the disbursement float
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => setShowAssignModal(false)}
                    className="w-7 h-7 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-400 hover:text-slate-700 transition-colors flex items-center justify-center cursor-pointer"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>

                <form onSubmit={handleAssignOfficerSubmit} className="space-y-3.5">
                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Select Staff Member <span className="text-rose-500">*</span>
                    </label>
                    <select
                      value={selectedOfficerId}
                      onChange={(e) => setSelectedOfficerId(Number(e.target.value) || '')}
                      required
                      className="w-full px-3 py-2.5 bg-white border border-[#EAE6DD] rounded-xl font-medium text-xs text-slate-800 focus:border-[#0084D1] outline-none cursor-pointer"
                    >
                      <option value="">-- Choose active staff member --</option>
                      {staffDirectory.map((u) => (
                        <option key={u.id} value={u.id}>
                          {u.name} ({u.roleName} - {u.email})
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="text-[11px] font-extrabold uppercase tracking-wider text-[#1B365D] block mb-1">
                      Initial Float Balance (Γé╣)
                    </label>
                    <input
                      type="number"
                      min="0"
                      step="0.01"
                      value={initialBalance}
                      onChange={(e) => setInitialBalance(e.target.value)}
                      placeholder="0.00"
                      className="w-full px-3.5 py-2.5 bg-white border border-[#EAE6DD] rounded-xl font-bold text-sm text-[#1B365D] focus:border-[#0084D1] outline-none"
                    />
                  </div>

                  <div className="pt-2 flex justify-end gap-2 border-t border-[#EAE6DD]">
                    <button
                      type="button"
                      onClick={() => setShowAssignModal(false)}
                      className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs transition-all cursor-pointer"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      disabled={assignSubmitting}
                      className="px-5 py-2 rounded-xl bg-gradient-to-r from-[#1B365D] to-[#0084D1] hover:from-[#142845] hover:to-[#0074b8] text-white font-extrabold text-xs shadow-md shadow-blue-900/15 disabled:opacity-50 transition-all cursor-pointer"
                    >
                      {assignSubmitting ? 'Assigning...' : 'Confirm Assignment'}
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        )}

        {/* Proof Lightbox */}
        {previewProofUrl && (
          <div className="fixed inset-0 z-70 bg-black/70 backdrop-blur-xs flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl max-w-lg w-full p-4 space-y-3 shadow-2xl border">
              <div className="flex items-center justify-between border-b pb-2">
                <span className="font-bold text-sm">Payment Receipt Proof</span>
                <button
                  type="button"
                  onClick={() => setPreviewProofUrl(null)}
                  className="p-1 text-slate-400 hover:text-slate-700"
                >
                  Γ£ò
                </button>
              </div>
              <div className="bg-slate-900 rounded-xl p-2 flex items-center justify-center">
                <img
                  src={previewProofUrl}
                  alt="Proof Full Size"
                  className="max-h-[70vh] object-contain rounded-lg"
                />
              </div>
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={() => window.open(previewProofUrl, '_blank')}
                  className="px-3 py-1.5 rounded-lg bg-[#1B365D] text-white font-bold text-xs"
                >
                  Open in New Tab
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import {
  X,
  CheckCircle2,
  Upload,
  AlertCircle,
  Copy,
  Check,
  AlertTriangle,
  ArrowRight,
} from 'lucide-react';
import { DisbursementRequest } from '@etaxwala/types';
import { useAuthStore } from '@/store/auth-store';

interface FulfillPaymentModalProps {
  isOpen: boolean;
  onClose: () => void;
  request: DisbursementRequest | null;
  onSuccess: (updated: DisbursementRequest) => void;
}

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

export const FulfillPaymentModal: React.FC<FulfillPaymentModalProps> = ({
  isOpen,
  onClose,
  request,
  onSuccess,
}) => {
  const { staffToken } = useAuthStore();
  const [walletBalance, setWalletBalance] = useState<number | null>(null);
  const [loadingWallet, setLoadingWallet] = useState(false);
  const [selectedProofFile, setSelectedProofFile] = useState<File | null>(null);
  const [proofPreview, setProofPreview] = useState<string | null>(null);
  const [utrNumber, setUtrNumber] = useState('');
  const [copiedUpi, setCopiedUpi] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen && staffToken) {
      fetchWallet();
    }
  }, [isOpen, staffToken, fetchWallet]);

  const fetchWallet = async () => {
    setLoadingWallet(true);
    try {
      const res = await fetch(`${API_BASE}/v1/disbursements/wallet`, {
        headers: { Authorization: `Bearer ${staffToken}` },
      });
      const data = await res.json();
      if (data.success && data.data) {
        setWalletBalance(Number(data.data.balance));
      }
    } catch (err) {
      console.error('Fetch wallet error:', err);
    } finally {
      setLoadingWallet(false);
    }
  };

  if (!isOpen || !request) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setSelectedProofFile(file);
      const reader = new FileReader();
      reader.onload = () => setProofPreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedUpi(true);
    setTimeout(() => setCopiedUpi(false), 2000);
  };

  const qrImageUrl = request.qrCodeUrl?.startsWith('http')
    ? request.qrCodeUrl
    : `${API_BASE}${request.qrCodeUrl}`;

  const reqAmount = Number(request.amount);
  const isInsufficientFloat = walletBalance !== null && walletBalance < reqAmount;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    if (!selectedProofFile) {
      setErrorMsg('Mandatory payment screenshot receipt is required as proof.');
      return;
    }

    if (isInsufficientFloat) {
      setErrorMsg(
        `Insufficient Float Balance! Current balance is Γé╣${walletBalance?.toLocaleString('en-IN')}, required is Γé╣${reqAmount.toLocaleString('en-IN')}. Please request Admin to Top Up.`
      );
      return;
    }

    setSubmitting(true);

    try {
      const formData = new FormData();
      formData.append('paymentProof', selectedProofFile);
      if (utrNumber.trim()) formData.append('utrNumber', utrNumber.trim());

      const res = await fetch(`${API_BASE}/v1/disbursements/requests/${request.id}/fulfill`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${staffToken}`,
        },
        body: formData,
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || 'Failed to record payment fulfillment.');
      }

      onSuccess(data.data);
      onClose();
    } catch (err: any) {
      console.error('Fulfill error:', err);
      setErrorMsg(err.message || 'Failed to submit payment proof.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/60 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl max-w-lg w-full border border-[#EAE6DD] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-150 flex flex-col max-h-[92vh]">
        {/* Signature ETaxwala Multicolor Top Accent Bar */}
        <div className="h-1.5 w-full bg-gradient-to-r from-[#0084D1] via-[#7C3AED] via-[#E11D48] to-[#F97316] shrink-0" />

        {/* Top Header */}
        <div className="px-6 py-4 bg-white border-b border-[#EAE6DD] flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-emerald-600 to-teal-700 text-white flex items-center justify-center shadow-md shadow-emerald-900/15 border border-emerald-400/20">
              <CheckCircle2 className="w-5 h-5 text-emerald-200" />
            </div>
            <div>
              <h3 className="text-base sm:text-lg font-black text-[#1B365D] tracking-tight">
                Fulfill Disbursement Payment
              </h3>
              <p className="text-xs text-slate-500 font-medium">
                Pay to attached QR/UPI & attach receipt proof for Admin audit
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-slate-100 hover:bg-slate-200 text-slate-400 hover:text-slate-700 transition-colors flex items-center justify-center cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Content */}
        <form
          onSubmit={handleSubmit}
          className="p-6 overflow-y-auto space-y-4 flex-1 text-slate-800 text-xs"
        >
          {errorMsg && (
            <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-rose-700 flex items-center gap-2">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{errorMsg}</span>
            </div>
          )}

          {/* Target Amount & Float Balance Indicator */}
          <div className="grid grid-cols-2 gap-3 p-4 bg-slate-50 border border-slate-200 rounded-2xl">
            <div>
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block mb-0.5">
                Amount to Pay
              </span>
              <div className="text-xl font-black text-[#1B365D]">
                Γé╣{reqAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
              </div>
              <p className="text-[11px] text-slate-500 truncate mt-0.5">
                For {request.purposeCategory}
              </p>
            </div>

            <div className="text-right">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block mb-0.5">
                Available Float Balance
              </span>
              <div
                className={`text-xl font-black ${isInsufficientFloat ? 'text-rose-600' : 'text-emerald-700'}`}
              >
                {loadingWallet
                  ? '...'
                  : walletBalance !== null
                    ? `Γé╣${walletBalance.toLocaleString('en-IN', { minimumFractionDigits: 2 })}`
                    : 'N/A'}
              </div>
              {isInsufficientFloat ? (
                <span className="inline-flex items-center gap-1 text-[10px] font-bold text-rose-600 bg-rose-100 px-2 py-0.2 rounded-full mt-0.5">
                  <AlertTriangle className="w-3 h-3" /> Insufficient Float
                </span>
              ) : (
                <span className="text-[10px] text-emerald-600 font-medium mt-0.5 block">
                  Sufficient company funds
                </span>
              )}
            </div>
          </div>

          {/* Insufficient balance warning alert */}
          {isInsufficientFloat && (
            <div className="p-3 bg-amber-50 border border-amber-300 rounded-xl text-amber-800 text-[11px] space-y-1">
              <p className="font-bold flex items-center gap-1.5">
                <AlertTriangle className="w-4 h-4 text-amber-600" /> Insufficient Expense Float
              </p>
              <p>
                Your accounts balance is lower than Γé╣{reqAmount.toLocaleString('en-IN')}. Please ask
                Admin to top up your float before fulfilling this payment.
              </p>
            </div>
          )}

          {/* Payment Destination (UPI or QR) */}
          <div className="p-4 bg-white border border-[#EAE6DD] rounded-2xl space-y-3">
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block">
              Staff Recipient Details
            </span>

            {request.upiId ? (
              <div className="space-y-1.5">
                <label className="text-[11px] text-slate-600 font-medium block">
                  Scan / Pay to UPI ID:
                </label>
                <div className="flex items-center justify-between bg-slate-50 px-3 py-2 rounded-xl border border-slate-200">
                  <span className="font-mono font-bold text-sm text-[#1B365D] select-all">
                    {request.upiId}
                  </span>
                  <button
                    type="button"
                    onClick={() => copyToClipboard(request.upiId!)}
                    className="px-2.5 py-1 rounded-lg bg-[#1B365D] hover:bg-[#152a48] text-white text-[11px] font-bold transition-all flex items-center gap-1"
                  >
                    {copiedUpi ? (
                      <>
                        <Check className="w-3.5 h-3.5 text-emerald-400" /> Copied!
                      </>
                    ) : (
                      <>
                        <Copy className="w-3.5 h-3.5" /> Copy UPI
                      </>
                    )}
                  </button>
                </div>
              </div>
            ) : request.qrCodeUrl ? (
              <div className="space-y-2 text-center">
                <label className="text-[11px] text-slate-600 font-medium block text-left">
                  Scan QR Code with Phone / Banking App:
                </label>
                <div className="inline-block p-3 bg-slate-50 rounded-2xl border border-slate-200">
                  <img
                    src={qrImageUrl}
                    alt="Staff QR Code"
                    className="max-h-56 w-auto object-contain rounded-xl mx-auto shadow-xs cursor-pointer"
                    onClick={() => window.open(qrImageUrl, '_blank')}
                    title="Click to expand QR in new tab"
                  />
                </div>
                <p className="text-[10px] text-slate-400">
                  Click image to view in new tab or scan directly from screen
                </p>
              </div>
            ) : null}
          </div>

          {/* Mandatory Payment Proof Attachment */}
          <div className="space-y-2">
            <label className="font-bold text-slate-700 flex items-center justify-between">
              <span>
                Upload Payment Screenshot Receipt <span className="text-rose-500">*</span>
              </span>
              <span className="text-[10px] text-slate-400 font-normal">
                Compulsory proof for audit
              </span>
            </label>

            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="image/png,image/jpeg,image/webp,application/pdf"
              className="hidden"
            />

            {proofPreview ? (
              <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-2xl flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <img
                    src={proofPreview}
                    alt="Proof Preview"
                    className="w-16 h-16 object-cover rounded-xl border border-emerald-300 bg-white"
                  />
                  <div>
                    <p className="font-bold text-slate-900 text-xs truncate max-w-[220px]">
                      {selectedProofFile?.name}
                    </p>
                    <p className="text-[10px] text-emerald-700 font-semibold flex items-center gap-1">
                      <Check className="w-3.5 h-3.5" /> Payment Proof attached
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    setSelectedProofFile(null);
                    setProofPreview(null);
                  }}
                  className="p-1 text-slate-400 hover:text-rose-600 rounded-full"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <div
                onClick={() => fileInputRef.current?.click()}
                className="border-2 border-dashed border-slate-300 hover:border-emerald-600 bg-slate-50 hover:bg-white rounded-2xl p-5 text-center cursor-pointer transition-all space-y-1.5"
              >
                <Upload className="w-6 h-6 mx-auto text-slate-400" />
                <p className="font-bold text-slate-700 text-xs">
                  Attach screenshot from GPay / PhonePe / NetBanking
                </p>
                <p className="text-[10px] text-slate-400">PNG, JPG, WEBP or PDF receipt</p>
              </div>
            )}
          </div>

          {/* UTR Number */}
          <div>
            <label className="font-bold text-slate-700 block mb-1.5">
              UTR / Transaction Reference Number (Optional)
            </label>
            <input
              type="text"
              value={utrNumber}
              onChange={(e) => setUtrNumber(e.target.value)}
              placeholder="e.g. 429182910248 or UPI Ref ID"
              className="w-full px-3.5 py-2.5 bg-white border border-[#EAE6DD] rounded-xl font-mono text-xs text-slate-800 focus:outline-none focus:border-emerald-600"
            />
          </div>
        </form>

        {/* Modal Footer */}
        <div className="px-6 py-4 bg-white border-t border-[#EAE6DD] flex items-center justify-end gap-2.5 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs transition-all cursor-pointer"
          >
            Cancel
          </button>
          <button
            type="submit"
            onClick={handleSubmit}
            disabled={submitting || !selectedProofFile || isInsufficientFloat}
            className="px-6 py-2.5 rounded-xl bg-gradient-to-r from-emerald-600 via-teal-600 to-teal-700 hover:from-emerald-700 hover:to-teal-800 text-white font-extrabold text-xs transition-all shadow-md shadow-emerald-900/15 disabled:opacity-50 flex items-center gap-2 active:scale-98 cursor-pointer"
          >
            {submitting ? 'Recording Fulfillment...' : 'Confirm & Disburse Payment'}
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import {
  Plus,
  Trash2,
  Edit3,
  MoreVertical,
  Calendar,
  Send,
  X,
  UserPlus,
  DollarSign,
  CheckCircle2,
  AlertTriangle,
  ListTodo,
  PlusCircle,
  Tag,
  Loader2,
  ShieldAlert,
} from 'lucide-react';

interface CustomerItem {
  id: number;
  orderId?: number | null;
  packageId?: string | null;
  serviceId?: number;
  name: string;
  company: string;
  subCustomer?: string;
  mobile: string;
  email: string;
  state: string;
  city: string;
  category: string;
  service: string;
  cp_type: number; // 1=Basic 2=Standard 3=Premium 4=Diamond 5=Custom
  type: string;
  addedBy: string;
  total: number;
  paid: number;
  unpaid: number;
  dueDate: string;
}

// DB category type
interface CategoryItem {
  category_id: number;
  category_name: string;
}
// DB service type
interface ServiceItem {
  service_id: number;
  service_name: string;
  service_price: number;
  effective_price?: number;  // service_price - cp_discount (price to charge)
  category_id?: number;
  category_name?: string;
  cp_type?: number; // 1=Basic 2=Standard 3=Premium 4=Diamond 0=none
  cp_id?: number;   // combo_packages primary key
  cp_discount?: number;
}

export default function CrmAccountsPage() {
  const [customers, setCustomers] = useState<CustomerItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [pageSize, setPageSize] = useState(10);
  const [activeMenuId, setActiveMenuId] = useState<number | null>(null);

  // Dynamic categories & services from DB
  const [dbCategories, setDbCategories] = useState<CategoryItem[]>([]);
  const [dbServicesByCategory, setDbServicesByCategory] = useState<ServiceItem[]>([]);
  const [allDbServices, setAllDbServices] = useState<ServiceItem[]>([]);
  const [loadingCategories, setLoadingCategories] = useState(false);
  const [loadingServices, setLoadingServices] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  // CP Type filter for customer table (0=All, 1=Basic, 2=Standard, 3=Premium, 4=Diamond, 5=Custom)
  const [cpTypeFilter, setCpTypeFilter] = useState(0);
  // CP Type state for Add Order and Create Customer modals
  const [_orderCpType, setOrderCpType] = useState(0);
  const [orderCpId, setOrderCpId] = useState(0);
  const [createCustCpType, setCreateCustCpType] = useState(0);
  const [createCustCpId, setCreateCustCpId] = useState(0);


  const customDropdownRef = React.useRef<HTMLDivElement>(null);

  const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

  // Fetch real customers from database
  const fetchCustomers = useCallback(() => {
    setLoading(true);
    const limitParam = pageSize === -1 ? 'all' : pageSize;
    fetch(`${API_BASE}/v1/crm/customers?limit=${limitParam}`)
      .then((res) => res.json())
      .then((data) => {
        if (data?.success && Array.isArray(data?.data)) {
          const mapped: CustomerItem[] = data.data.map((c: any, i: number) => ({
            id: c.id || i + 1,
            orderId: c.orderId || null,
            packageId: c.packageId || null,
            serviceId: c.serviceId || 1,
            name: c.name || 'Client',
            company: c.business || c.company || 'Company',
            subCustomer: c.subCustomer || '',
            mobile: c.mobile || c.contact || '9876543210',
            email: c.email || 'client@etaxwala.in',
            state: c.state || 'Maharashtra',
            city: c.city || 'Pune',
            category: c.category || 'Taxation & Return Filing',
            service: c.service || 'Advisory',
            cp_type: Number(c.cp_type) || 0,
            type: c.type || 'Basic',
            addedBy: c.addedBy || `Staff #${c.added_by || 1}`,
            total: c.total !== undefined ? c.total : 1499,
            paid: c.paid !== undefined ? c.paid : 0,
            unpaid: c.unpaid !== undefined ? c.unpaid : 1499,
            dueDate: c.dueDate || 'ΓÇö',
          }));
          setCustomers(mapped);
          if (data.total) setTotalCount(data.total);
        }
      })
      .catch((err) => console.error('Failed to fetch customers', err))
      .finally(() => setLoading(false));
  }, [API_BASE, pageSize]);

  useEffect(() => {
    fetchCustomers();
  }, [fetchCustomers]);

  // Click outside to close custom package dropdown
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (customDropdownRef.current && !customDropdownRef.current.contains(event.target as Node)) {
        setIsCustomDropdownOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Fetch categories from DB on mount
  useEffect(() => {
    setLoadingCategories(true);
    fetch(`${API_BASE}/v1/crm/categories`)
      .then((res) => res.json())
      .then((data) => {
        if (data?.success && Array.isArray(data?.data) && data.data.length > 0) {
          setDbCategories(data.data);
        }
      })
      .catch(() => {})
      .finally(() => setLoadingCategories(false));
  }, [API_BASE]);

  // Fetch all services for custom package multi-select
  useEffect(() => {
    fetch(`${API_BASE}/v1/crm/all-services`)
      .then((res) => res.json())
      .then((data) => {
        if (data?.success && Array.isArray(data?.data) && data.data.length > 0) {
          setAllDbServices(data.data);
        }
      })
      .catch(() => {});
  }, [API_BASE]);

  const location = useLocation();

  // Modals state
  const [activeCustomer, setActiveCustomer] = useState<CustomerItem | null>(null);
  const [isAddCustomerOpen, setIsAddCustomerOpen] = useState(false);
  const [isUpdateCustomerOpen, setIsUpdateCustomerOpen] = useState(
    new URLSearchParams(location.search).get('update') === '1'
  );
  const [isAddOrderOpen, setIsAddOrderOpen] = useState(
    new URLSearchParams(location.search).get('order') === '1'
  );
  const [isEditSubCustomerOpen, setIsEditSubCustomerOpen] = useState(false);
  const [isAddAppointmentOpen, setIsAddAppointmentOpen] = useState(
    new URLSearchParams(location.search).get('appointment') === '1'
  );
  const [isTasksDrawerOpen, setIsTasksDrawerOpen] = useState(
    new URLSearchParams(location.search).get('drawer') === '1'
  );

  // Form states
  const [subCustomerName, setSubCustomerName] = useState('');
  const [appointmentAdvisor, setAppointmentAdvisor] = useState('Mr. Vaijnath Sir');
  const [appointmentDate, setAppointmentDate] = useState('2026-09-06');
  const [appointmentTime, setAppointmentTime] = useState('14:30');
  const [appointmentDesc, setAppointmentDesc] = useState('');

  // Add Customer Form State (Old CRM Wizard Replica)
  const [addCustomerName, setAddCustomerName] = useState('');
  const [addBusinessName, setAddBusinessName] = useState('');
  const [addEmail, setAddEmail] = useState('');
  const [addMobile, setAddMobile] = useState('');
  const [addState, setAddState] = useState('Maharashtra');
  const [addCity, setAddCity] = useState('Chhatrapati Sambhajinagar');
  const [isCustomPkg, setIsCustomPkg] = useState('0'); // '0' = No, '1' = Yes
  const [selectedCategoryId, setSelectedCategoryId] = useState<number>(0);
  const [selectedCategoryName, setSelectedCategoryName] = useState('');
  const [selectedServiceId, setSelectedServiceId] = useState<number>(0); // actual service_id for form submit
  const [selectedCpId, setSelectedCpId] = useState<number>(0);           // cp_id for dropdown display
  const [selectedServiceName, setSelectedServiceName] = useState('');
  const [customPkgName, setCustomPkgName] = useState('');
  const [selectedCustomServiceIds, setSelectedCustomServiceIds] = useState<number[]>([]);
  const [isCustomDropdownOpen, setIsCustomDropdownOpen] = useState(false);
  const [isOrderCustomDropdownOpen, setIsOrderCustomDropdownOpen] = useState(false);
  const [isCreateCustCustomDropdownOpen, setIsCreateCustCustomDropdownOpen] = useState(false);
  // Service pickers (custom div dropdowns with colored cp_type badges)
  const [isAddCustServiceOpen, setIsAddCustServiceOpen] = useState(false);
  const [isOrderServiceOpen, setIsOrderServiceOpen] = useState(false);
  const [isCreateCustServiceOpen, setIsCreateCustServiceOpen] = useState(false);

  const [couponCode, setCouponCode] = useState('');
  const [couponMessage, setCouponMessage] = useState<{
    type: 'success' | 'error';
    text: string;
  } | null>(null);
  const [isValidatingCoupon, setIsValidatingCoupon] = useState(false);
  const [actualPrice, setActualPrice] = useState(0);
  const [discountAmount, setDiscountAmount] = useState(0);
  const [paymentMode, setPaymentMode] = useState('1'); // 1: No EMI, 2: 2 EMI, 3: 3 EMI
  const [paidAmount, setPaidAmount] = useState(0);
  const [dueDate1, setDueDate1] = useState(
    new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const [dueDate2, setDueDate2] = useState(
    new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const [comment, setComment] = useState('');

  // Fetch services when category changes
  const fetchServicesForCategory = useCallback(
    (catId: number) => {
      if (!catId) return;
      setLoadingServices(true);
      fetch(`${API_BASE}/v1/crm/services-by-category/${catId}`)
        .then((res) => res.json())
        .then((data) => {
          if (data?.success && Array.isArray(data?.data) && data.data.length > 0) {
            // Normalize all numeric fields to Number ΓÇö serializeBigInt converts BigInt ΓåÆ string
            // so cp_id arrives as "42" but comparisons need strict 42 === 42
            const normalized = data.data.map((s: ServiceItem) => ({
              ...s,
              cp_id: s.cp_id !== undefined ? Number(s.cp_id) : undefined,
              service_id: Number(s.service_id),
              cp_type: s.cp_type !== undefined ? Number(s.cp_type) : undefined,
              cp_discount: s.cp_discount !== undefined ? Number(s.cp_discount) : undefined,
              service_price: Number(s.service_price),
              effective_price: s.effective_price !== undefined ? Number(s.effective_price) : undefined,
            }));
            setDbServicesByCategory(normalized);
            // Auto-select first service (set both service_id for submit and cp_id for display)
            const first = normalized[0] as ServiceItem;
            setSelectedServiceId(Number(first.service_id));
            setSelectedCpId(Number(first.cp_id ?? 0));
            setSelectedServiceName(first.service_name);
            const price = first.effective_price ?? first.service_price;
            setActualPrice(Number(price));
            setPaidAmount(Number(price));
          }

        })
        .catch(() => {})
        .finally(() => setLoadingServices(false));
    },
    [API_BASE]
  );

  // When categories load, auto-select first category and fetch its services
