  Cancelled: 'badge-red',
};

export default function CrmAppointmentsPage() {
  const [appointments, setAppointments] = useState<Appointment[]>(INITIAL_APPOINTMENTS);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [modeFilter, setModeFilter] = useState('all');
  const [selectedAppointment, setSelectedAppointment] = useState<Appointment | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const filtered = appointments.filter((a) => {
    const matchesSearch =
      a.name.toLowerCase().includes(search.toLowerCase()) ||
      a.mobile.includes(search) ||
      a.city.toLowerCase().includes(search.toLowerCase());
    const matchesStatus = statusFilter === 'all' || a.status === statusFilter;
    const matchesMode = modeFilter === 'all' || a.mode === modeFilter;
    return matchesSearch && matchesStatus && matchesMode;
  });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const updateStatus = (id: number, status: Appointment['status']) => {
    setAppointments((prev) => prev.map((a) => (a.id === id ? { ...a, status } : a)));
    showToast(`Appointment marked as ${status}`);
  };

  const today = new Date().toISOString().split('T')[0];
  const todayCount = appointments.filter((a) => a.date === today).length;
  const pendingCount = appointments.filter((a) => a.status === 'Pending').length;
  const confirmedCount = appointments.filter((a) => a.status === 'Confirmed').length;
  const completedCount = appointments.filter((a) => a.status === 'Completed').length;

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-bold text-[#1B365D] flex items-center gap-2">
            <Calendar className="w-5 h-5 text-[#00A896]" />
            Appointments
          </h1>
          <p className="text-xs text-slate-500 mt-0.5">
            View, confirm and manage all customer appointments across channels.
          </p>
        </div>
        <button
          onClick={() => showToast('Export functionality will be connected to API', 'success')}
          className="px-4 py-2 rounded-lg btn-multicolor text-xs font-semibold flex items-center gap-1.5"
        >
          <Download className="w-3.5 h-3.5" />
          Export
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="card p-4 border border-slate-100">
          <p className="text-[10px] uppercase tracking-wide text-slate-500 font-bold">Today</p>
          <p className="text-2xl font-bold text-[#1B365D] mt-1">{todayCount}</p>
        </div>
        <div className="card p-4 border border-slate-100">
          <p className="text-[10px] uppercase tracking-wide text-slate-500 font-bold">Pending</p>
          <p className="text-2xl font-bold text-amber-600 mt-1">{pendingCount}</p>
        </div>
        <div className="card p-4 border border-slate-100">
          <p className="text-[10px] uppercase tracking-wide text-slate-500 font-bold">Confirmed</p>
          <p className="text-2xl font-bold text-blue-600 mt-1">{confirmedCount}</p>
        </div>
        <div className="card p-4 border border-slate-100">
          <p className="text-[10px] uppercase tracking-wide text-slate-500 font-bold">Completed</p>
          <p className="text-2xl font-bold text-emerald-600 mt-1">{completedCount}</p>
        </div>
      </div>

      {/* Toolbar */}
      <div className="card p-3 border border-slate-100 flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by name, mobile or city..."
            className="input w-full pl-9 text-xs"
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="input text-xs"
        >
          <option value="all">All Status</option>
          <option value="Pending">Pending</option>
          <option value="Confirmed">Confirmed</option>
          <option value="Completed">Completed</option>
          <option value="Cancelled">Cancelled</option>
        </select>
        <select
          value={modeFilter}
          onChange={(e) => setModeFilter(e.target.value)}
          className="input text-xs"
        >
          <option value="all">All Modes</option>
          <option value="Telephonic">Telephonic</option>
          <option value="Office Visit">Office Visit</option>
          <option value="Video Call">Video Call</option>
        </select>
      </div>

      {/* Table */}
      <div className="card border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="table-crm w-full text-xs">
            <thead className="bg-[#FAF9F5] border-b border-[#EAE6DD]">
              <tr>
                <th className="text-left px-4 py-3 font-bold text-slate-600">Customer</th>
                <th className="text-left px-4 py-3 font-bold text-slate-600">Date & Time</th>
                <th className="text-center px-4 py-3 font-bold text-slate-600">Mode</th>
                <th className="text-left px-4 py-3 font-bold text-slate-600">City</th>
                <th className="text-center px-4 py-3 font-bold text-slate-600">Status</th>
                <th className="text-left px-4 py-3 font-bold text-slate-600">Source</th>
                <th className="text-right px-4 py-3 font-bold text-slate-600">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.map((appt) => {
                const ModeIcon = MODE_ICONS[appt.mode];
                return (
                  <tr key={appt.id} className="hover:bg-slate-50">
                    <td className="px-4 py-3">
                      <div className="font-semibold text-slate-900">{appt.name}</div>
                      <div className="text-[10px] text-slate-500">{appt.mobile}</div>
                    </td>
                    <td className="px-4 py-3">
                      <div className="font-medium text-slate-800 flex items-center gap-1.5">
                        <Calendar className="w-3 h-3 text-slate-400" />
                        {appt.date}
                      </div>
                      <div className="text-[10px] text-slate-500 flex items-center gap-1.5">
                        <Clock className="w-3 h-3 text-slate-400" />
                        {appt.time}
                      </div>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <span className="badge badge-navy text-[10px] flex items-center gap-1 w-fit mx-auto">
                        <ModeIcon className="w-3 h-3" />
                        {appt.mode}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-slate-600">{appt.city}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`badge text-[10px] ${STATUS_BADGES[appt.status]}`}>
                        {appt.status}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-slate-600">{appt.addedBy}</td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          onClick={() => setSelectedAppointment(appt)}
                          className="px-2 py-1 rounded-lg text-[10px] font-semibold btn-multicolor"
                        >
                          View
                        </button>
                        {appt.status === 'Pending' && (
                          <button
                            onClick={() => updateStatus(appt.id, 'Confirmed')}
                            className="px-2 py-1 rounded-xl text-[10px] font-semibold btn-multicolor"
                          >
                            Confirm
                          </button>
                        )}
                        {appt.status === 'Confirmed' && (
                          <button
                            onClick={() => updateStatus(appt.id, 'Completed')}
                            className="px-2 py-1 rounded-xl text-[10px] font-semibold btn-multicolor"
                          >
                            Complete
                          </button>
                        )}
                        {(appt.status === 'Pending' || appt.status === 'Confirmed') && (
                          <button
                            onClick={() => updateStatus(appt.id, 'Cancelled')}
                            className="px-2 py-1 rounded-xl text-[10px] font-semibold btn-multicolor"
                          >
                            Cancel
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-10 text-center text-slate-400">
                    No appointments found matching your filters.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Appointment Detail Modal */}
      {selectedAppointment && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden">
            <div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-sm font-bold text-[#1B365D]">Appointment Details</h2>
              <button
                onClick={() => setSelectedAppointment(null)}
                className="text-slate-400 hover:text-slate-600"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
            <div className="p-5 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Customer</label>
                  <p className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
                    <User className="w-3.5 h-3.5 text-slate-400" />
                    {selectedAppointment.name}
                  </p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Mobile</label>
                  <p className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
                    <Phone className="w-3.5 h-3.5 text-slate-400" />
                    {selectedAppointment.mobile}
                  </p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Email</label>
                  <p className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
                    <Mail className="w-3.5 h-3.5 text-slate-400" />
                    {selectedAppointment.email}
                  </p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">City</label>
                  <p className="text-sm font-semibold text-slate-900 flex items-center gap-1.5">
                    <MapPin className="w-3.5 h-3.5 text-slate-400" />
                    {selectedAppointment.city}
                  </p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Date</label>
                  <p className="text-sm font-semibold text-slate-900">{selectedAppointment.date}</p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Time</label>
                  <p className="text-sm font-semibold text-slate-900">{selectedAppointment.time}</p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Mode</label>
                  <p className="text-sm font-semibold text-slate-900">{selectedAppointment.mode}</p>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Status</label>
                  <p className="text-sm font-semibold">
                    <span
                      className={`badge text-[10px] ${STATUS_BADGES[selectedAppointment.status]}`}
                    >
                      {selectedAppointment.status}
                    </span>
                  </p>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Message</label>
                <div className="p-3 rounded-xl bg-[#FAF9F5] border border-slate-100 text-xs text-slate-700">
                  <MessageSquare className="w-3.5 h-3.5 text-slate-400 inline mr-1.5" />
                  {selectedAppointment.message || 'No message provided.'}
                </div>
              </div>
            </div>
            <div className="px-5 py-4 border-t border-slate-100 flex justify-end gap-2">
              <button
                onClick={() => setSelectedAppointment(null)}
                className="px-4 py-2 rounded-lg btn-multicolor text-xs font-semibold"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast && (
        <div
          className={`fixed bottom-5 right-5 z-50 px-4 py-3 rounded-xl shadow-lg text-xs font-semibold ${
            toast.type === 'error' ? 'bg-rose-600 text-white' : 'bg-emerald-600 text-white'
          }`}
        >
          {toast.message}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/auth-store';
import { RoleType } from '@etaxwala/types';
import {
  Phone, PhoneCall, PhoneOff, PhoneMissed, Clock, TrendingUp,
  Users, Search, CalendarDays, Download, BarChart3, Award,
  AlertCircle, ChevronDown, Filter, RefreshCw, History, UserCheck,
  Building2, Tag, ArrowUpRight, ArrowDownLeft
} from 'lucide-react';

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

interface EmployeeAnalytics {
  user_id?: number;
  name?: string;
  role_id?: number;
  total_calls: number;
  answered: number;
  missed: number;
  rejected: number;
  not_answered: number;
  total_talk_time_seconds: number;
  avg_call_duration_seconds: number;
  unique_leads_called: number;
  answer_rate: number;
}

interface CallSummaryStats {
  total_calls: number;
  incoming_calls: number;
  outgoing_calls: number;
  missed_calls: number;
  total_duration: number;
}

interface CallHistoryItem {
  id: number;
  lead_id: number | null;
  lead_name: string;
  lead_contact: string;
  lead_source: string;
  phone_number: string;
  direction: 'incoming' | 'outgoing';
  status: string;
  call_type: string;
  duration_seconds: number;
  user_id: number;
  user_name: string;
  called_at: string;
}

interface StaffOption {
  id: number;
  name: string;
  role_id: number;
}

function formatDuration(seconds: number): string {
  if (seconds === 0) return '0s';
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}h ${m}m`;
  if (m > 0) return `${m}m ${s}s`;
  return `${s}s`;
}

function StatCard({
  icon: Icon, label, value, sub, color, bg,
}: {
  icon: React.ElementType; label: string; value: string | number;
  sub?: string; color: string; bg: string;
}) {
  return (
    <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-start justify-between mb-2">
        <div className="w-9 h-9 rounded-xl flex items-center justify-center shrink-0" style={{ background: bg }}>
          <Icon className="w-4 h-4" style={{ color }} />
        </div>
      </div>
      <p className="text-xl font-bold font-display text-slate-900">{value}</p>
      <p className="text-xs font-semibold text-slate-600 mt-0.5">{label}</p>
      {sub && <p className="text-[11px] text-slate-400 mt-0.5">{sub}</p>}
    </div>
  );
}

export default function CrmCallAnalyticsPage() {
  const { staffToken, staffUser } = useAuthStore();
  const [activeTab, setActiveTab] = useState<'history' | 'analytics'>('history');
  const [view, setView] = useState<'me' | 'team' | 'all'>('me');

  // Filters state
  const [staffList, setStaffList] = useState<StaffOption[]>([]);
  const [selectedStaff, setSelectedStaff] = useState<string>('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [callTypeFilter, setCallTypeFilter] = useState<string>('');
  const [leadSourceFilter, setLeadSourceFilter] = useState<string>('');
  const [search, setSearch] = useState('');

  // Call Report Summary state
  const [summaryTotal, setSummaryTotal] = useState<CallSummaryStats>({
    total_calls: 0, incoming_calls: 0, outgoing_calls: 0, missed_calls: 0, total_duration: 0,
  });
  const [summaryToday, setSummaryToday] = useState<CallSummaryStats>({
    total_calls: 0, incoming_calls: 0, outgoing_calls: 0, missed_calls: 0, total_duration: 0,
  });

  // Call History state
  const [historyLogs, setHistoryLogs] = useState<CallHistoryItem[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalHistoryCount, setTotalHistoryCount] = useState(0);

  // Leaderboard / Analytics state
  const [analytics, setAnalytics] = useState<EmployeeAnalytics | null>(null);
  const [teamData, setTeamData] = useState<EmployeeAnalytics[]>([]);
  const [analyticsLoading, setAnalyticsLoading] = useState(false);

  const isAdmin = (staffUser?.role === RoleType.SUPER_ADMIN || staffUser?.role === RoleType.ADMIN);
  const isManager = isAdmin || staffUser?.role === RoleType.SALES_MANAGER;

  const authHeaders = {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${staffToken}`,
  };

  // Fetch staff list for filters
  useEffect(() => {
    if (isManager || isAdmin) {
      fetch(`${API_BASE}/v1/call-logs/staff`, { headers: authHeaders })
        .then(res => res.json())
        .then(data => {
          if (data.success) setStaffList(data.data || []);
        })
        .catch(() => {});
    }
  }, []);

  const buildQueryParams = () => {
    const params = new URLSearchParams();
    if (dateFrom) params.append('from', dateFrom);
    if (dateTo) params.append('to', dateTo);
    if (selectedStaff) params.append('user_id', selectedStaff);
    if (callTypeFilter) params.append('call_type', callTypeFilter);
    if (leadSourceFilter) params.append('lead_source', leadSourceFilter);
    if (search) params.append('search', search);
    return params;
  };

  // Load summary stats (Total & Today)
  const loadSummaryStats = async () => {
    try {
      const params = buildQueryParams();
      const res = await fetch(`${API_BASE}/v1/call-logs/summary?${params.toString()}`, { headers: authHeaders });
      const data = await res.json();
      if (data.success && data.data) {
        setSummaryTotal(data.data.total);
        setSummaryToday(data.data.today);
      }
    } catch {
      // Demo fallback summary
      setSummaryTotal({ total_calls: 142, incoming_calls: 58, outgoing_calls: 84, missed_calls: 12, total_duration: 18450 });
      setSummaryToday({ total_calls: 18, incoming_calls: 7, outgoing_calls: 11, missed_calls: 2, total_duration: 2100 });
    }
  };

  // Load Call History table
  const loadCallHistory = async () => {
    setHistoryLoading(true);
    try {
      const params = buildQueryParams();
      params.append('page', page.toString());
      params.append('limit', '20');

      const res = await fetch(`${API_BASE}/v1/call-logs/history?${params.toString()}`, { headers: authHeaders });
      const data = await res.json();
      if (data.success) {
        setHistoryLogs(data.data || []);
        if (data.pagination) {
          setTotalPages(data.pagination.totalPages || 1);
          setTotalHistoryCount(data.pagination.total || 0);
        }
      }
    } catch {
      // Demo fallback history
      setHistoryLogs([
        {
          id: 1, lead_id: 101, lead_name: 'Rajesh Kumar', lead_contact: '+91 9876543210',
          lead_source: 'ETax', phone_number: '+91 9876543210', direction: 'outgoing', status: 'answered',
          call_type: 'outgoing', duration_seconds: 240, user_id: 2, user_name: 'Priya Sharma',
          called_at: new Date().toISOString(),
        },
        {
          id: 2, lead_id: 102, lead_name: 'Amit Patel', lead_contact: '+91 9812345678',
          lead_source: 'Sahakar Samridhi', phone_number: '+91 9812345678', direction: 'incoming', status: 'missed',
          call_type: 'incoming_missed', duration_seconds: 0, user_id: 3, user_name: 'Rahul Verma',
          called_at: new Date(Date.now() - 3600000).toISOString(),
        },
      ]);
    } finally {
      setHistoryLoading(false);
    }
  };

  // Load Leaderboard / Analytics
  const loadAnalytics = async () => {
    setAnalyticsLoading(true);
    try {
      const params = new URLSearchParams();
      if (dateFrom) params.append('from', dateFrom);
      if (dateTo) params.append('to', dateTo);

      if (view === 'me' || (!isManager && !isAdmin)) {
        const res = await fetch(`${API_BASE}/v1/call-logs/analytics/me?${params.toString()}`, { headers: authHeaders });
        const data = await res.json();
        if (data.success) setAnalytics(data.data);
      } else if (view === 'team') {
        const res = await fetch(`${API_BASE}/v1/call-logs/analytics/team?${params.toString()}`, { headers: authHeaders });
        const data = await res.json();
        if (data.success) setTeamData(data.data);
      } else {
        const res = await fetch(`${API_BASE}/v1/call-logs/analytics/all?${params.toString()}`, { headers: authHeaders });
        const data = await res.json();
        if (data.success) setTeamData(data.data);
      }
    } catch {
      if (view === 'me') {
        setAnalytics({
          total_calls: 127, answered: 89, missed: 24, rejected: 14,
          not_answered: 38, total_talk_time_seconds: 18420,
          avg_call_duration_seconds: 207, unique_leads_called: 63, answer_rate: 70,
        });
      } else {
        setTeamData([
          { user_id: 1, name: 'Priya Sharma', role_id: 7, total_calls: 143, answered: 112, missed: 20, rejected: 11, not_answered: 31, total_talk_time_seconds: 23040, avg_call_duration_seconds: 206, unique_leads_called: 78, answer_rate: 78 },
          { user_id: 2, name: 'Rahul Verma', role_id: 7, total_calls: 98, answered: 61, missed: 28, rejected: 9, not_answered: 37, total_talk_time_seconds: 12240, avg_call_duration_seconds: 201, unique_leads_called: 52, answer_rate: 62 },
        ]);
      }
    } finally {
      setAnalyticsLoading(false);
    }
  };

  useEffect(() => {
    loadSummaryStats();
    if (activeTab === 'history') {
      loadCallHistory();
    } else {
      loadAnalytics();
    }
  }, [activeTab, view, dateFrom, dateTo, selectedStaff, callTypeFilter, leadSourceFilter, page]);

  const handleRefresh = () => {
    loadSummaryStats();
    if (activeTab === 'history') loadCallHistory();
    else loadAnalytics();
  };

  const handleClearFilters = () => {
    setDateFrom('');
    setDateTo('');
    setSelectedStaff('');
    setCallTypeFilter('');
    setLeadSourceFilter('');
    setSearch('');
    setPage(1);
  };

  const renderLeadSourceBadge = (source: string) => {
    const srcUpper = (source || '').toUpperCase();
    if (srcUpper.includes('ETAX')) {
      return <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-blue-100 text-blue-800">ETax</span>;
    } else if (srcUpper.includes('SAHAKAR')) {
      return <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-emerald-100 text-emerald-800">Sahakar</span>;
    } else if (srcUpper.includes('UDYAMI')) {
      return <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-amber-100 text-amber-800">Udyami</span>;
    }
    return <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-slate-100 text-slate-700">{source || 'Direct'}</span>;
  };

  const renderCallTypeBadge = (direction: string, status: string) => {
    if (status === 'missed' || status === 'rejected') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-semibold bg-red-50 text-red-700 border border-red-200">
          <PhoneMissed className="w-3 h-3 text-red-500" />
          Missed Call
        </span>
      );
    }
    if (direction === 'incoming') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
          <ArrowDownLeft className="w-3 h-3 text-emerald-500" />
          Incoming
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-semibold bg-sky-50 text-sky-700 border border-sky-200">
        <ArrowUpRight className="w-3 h-3 text-sky-500" />
        Outgoing
      </span>
    );
  };

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-display font-bold text-slate-900 flex items-center gap-2">
            <PhoneCall className="w-6 h-6 text-brand-navy" />
            Call Report & Analytics
          </h1>
          <p className="text-sm text-slate-500 mt-0.5">
            Real-time call tracking, activity logs, and team performance report
          </p>
        </div>

        {/* Tab Selection */}
        <div className="flex bg-slate-100 rounded-xl p-1 gap-1 self-start">
          <button
            onClick={() => setActiveTab('history')}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 ${
              activeTab === 'history' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            <History className="w-3.5 h-3.5" />
            Call History
          </button>
          <button
            onClick={() => setActiveTab('analytics')}
            className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 ${
              activeTab === 'analytics' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            <BarChart3 className="w-3.5 h-3.5" />
            Analytics & Leaderboard
          </button>
        </div>
      </div>

      {/* Overview Stat Cards (Total vs Today breakdown) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Total Summary */}
        <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm">
          <div className="flex items-center justify-between border-b border-slate-100 pb-3 mb-3">
            <span className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
              <TrendingUp className="w-4 h-4 text-emerald-600" />
              Total Call Summary
            </span>
            <span className="text-[11px] text-slate-400 font-medium">Filtered Period</span>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
            <StatCard icon={PhoneCall} label="Total Calls" value={summaryTotal.total_calls} color="#003A66" bg="#EFF6FF" />
            <StatCard icon={ArrowDownLeft} label="Incoming" value={summaryTotal.incoming_calls} color="#059669" bg="#F0FDF4" />
            <StatCard icon={ArrowUpRight} label="Outgoing" value={summaryTotal.outgoing_calls} color="#0284C7" bg="#F0F9FF" />
            <StatCard icon={PhoneMissed} label="Missed" value={summaryTotal.missed_calls} color="#DC2626" bg="#FEF2F2" />
            <StatCard icon={Clock} label="Duration" value={formatDuration(summaryTotal.total_duration)} color="#D97706" bg="#FFFBEB" />
          </div>
        </div>

        {/* Today Summary */}
        <div className="bg-emerald-50/40 rounded-2xl border border-emerald-200/60 p-4 shadow-sm">
          <div className="flex items-center justify-between border-b border-emerald-100 pb-3 mb-3">
            <span className="text-xs font-bold text-emerald-800 uppercase tracking-wider flex items-center gap-1.5">
              <CalendarDays className="w-4 h-4 text-emerald-600" />
              Today's Calls ({new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })})
            </span>
            <span className="text-[11px] text-emerald-600 font-medium">Live sync</span>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
            <StatCard icon={PhoneCall} label="Total" value={summaryToday.total_calls} color="#047857" bg="#ECFDF5" />
            <StatCard icon={ArrowDownLeft} label="Incoming" value={summaryToday.incoming_calls} color="#059669" bg="#F0FDF4" />
            <StatCard icon={ArrowUpRight} label="Outgoing" value={summaryToday.outgoing_calls} color="#0284C7" bg="#F0F9FF" />
            <StatCard icon={PhoneMissed} label="Missed" value={summaryToday.missed_calls} color="#DC2626" bg="#FEF2F2" />
            <StatCard icon={Clock} label="Duration" value={formatDuration(summaryToday.total_duration)} color="#D97706" bg="#FFFBEB" />
          </div>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
        <div className="flex items-center justify-between">
          <span className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
            <Filter className="w-3.5 h-3.5 text-slate-500" /> Filters & Controls
          </span>
          <div className="flex items-center gap-2">
            {(dateFrom || dateTo || selectedStaff || callTypeFilter || leadSourceFilter || search) && (
              <button
                onClick={handleClearFilters}
                className="text-xs text-slate-500 hover:text-slate-700 underline font-medium"
              >
                Reset Filters
              </button>
            )}
            <button
              onClick={handleRefresh}
              className="p-1.5 text-slate-400 hover:text-slate-600 rounded-lg hover:bg-slate-100 transition-colors"
              title="Refresh"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-6 gap-3">
          {/* Staff Filter */}
          {(isManager || isAdmin) && (
            <div>
              <label className="text-[11px] font-semibold text-slate-500 block mb-1">Staff</label>
              <select
                value={selectedStaff}
                onChange={e => { setSelectedStaff(e.target.value); setPage(1); }}
                className="input text-xs py-1.5 w-full"
              >
                <option value="">All Staff</option>
                {staffList.map(s => (
                  <option key={s.id} value={s.id}>{s.name}</option>
                ))}
              </select>
            </div>
          )}

          {/* Date From */}
          <div>
            <label className="text-[11px] font-semibold text-slate-500 block mb-1">From Date</label>
            <input
              type="date"
              value={dateFrom}
              onChange={e => { setDateFrom(e.target.value); setPage(1); }}
              className="input text-xs py-1.5 w-full"
            />
          </div>

          {/* Date To */}
          <div>
            <label className="text-[11px] font-semibold text-slate-500 block mb-1">To Date</label>
            <input
              type="date"
              value={dateTo}
              onChange={e => { setDateTo(e.target.value); setPage(1); }}
              className="input text-xs py-1.5 w-full"
            />
          </div>

          {/* Call Type Filter */}
          <div>
            <label className="text-[11px] font-semibold text-slate-500 block mb-1">Call Type</label>
            <select
              value={callTypeFilter}
              onChange={e => { setCallTypeFilter(e.target.value); setPage(1); }}
              className="input text-xs py-1.5 w-full"
            >
              <option value="">All Types</option>
              <option value="incoming">Incoming</option>
              <option value="outgoing">Outgoing</option>
              <option value="missed">Missed</option>
            </select>
          </div>

          {/* Lead Source Filter */}
          <div>
            <label className="text-[11px] font-semibold text-slate-500 block mb-1">Lead Source</label>
            <select
              value={leadSourceFilter}
              onChange={e => { setLeadSourceFilter(e.target.value); setPage(1); }}
              className="input text-xs py-1.5 w-full"
            >
              <option value="">All Sources</option>
              <option value="ETax">ETax</option>
              <option value="Sahakar">Sahakar Samridhi</option>
              <option value="Udyami">Udyami Kisan</option>
            </select>
          </div>

          {/* Search Input */}
          <div>
            <label className="text-[11px] font-semibold text-slate-500 block mb-1">Search Lead/Contact</label>
            <div className="relative">
              <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Name or phone..."
                value={search}
                onChange={e => { setSearch(e.target.value); setPage(1); }}
                className="input text-xs py-1.5 pl-8 w-full"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      {activeTab === 'history' ? (
        <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
          <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
            <div>
              <h3 className="text-sm font-bold text-slate-900">Call Logs & Activity</h3>
              <p className="text-xs text-slate-400 mt-0.5">Showing {historyLogs.length} of {totalHistoryCount} total calls</p>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="table-crm w-full text-sm border-separate border-spacing-0">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Lead</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Contact</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Source</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Type</th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Duration & Time</th>
                  {(isManager || isAdmin) && (
                    <th className="text-left px-4 py-3 text-xs font-bold text-slate-500 uppercase">Staff User</th>
                  )}
                  <th className="text-right px-4 py-3 text-xs font-bold text-slate-500 uppercase">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {historyLoading ? (
                  Array.from({ length: 5 }).map((_, i) => (
                    <tr key={i}>
                      {Array.from({ length: isManager || isAdmin ? 7 : 6 }).map((_, j) => (
                        <td key={j} className="px-4 py-3">
                          <div className="h-4 bg-slate-100 rounded animate-pulse" />
                        </td>
                      ))}
                    </tr>
                  ))
                ) : historyLogs.length === 0 ? (
                  <tr>
                    <td colSpan={isManager || isAdmin ? 7 : 6} className="text-center py-12 text-slate-400 text-sm">
                      No call history records found matching criteria.
                    </td>
                  </tr>
                ) : (
                  historyLogs.map(log => (
                    <tr key={log.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-4 py-3 font-semibold text-slate-900">{log.lead_name}</td>
                      <td className="px-4 py-3 text-slate-600 font-mono text-xs">{log.lead_contact}</td>
                      <td className="px-4 py-3">{renderLeadSourceBadge(log.lead_source)}</td>
                      <td className="px-4 py-3">{renderCallTypeBadge(log.direction, log.status)}</td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-slate-900 text-xs">{formatDuration(log.duration_seconds)}</div>
                        <div className="text-[11px] text-slate-400">
                          {new Date(log.called_at).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </td>
                      {(isManager || isAdmin) && (
                        <td className="px-4 py-3 text-slate-700 text-xs font-medium">{log.user_name}</td>
                      )}
                      <td className="px-4 py-3 text-right text-xs text-slate-500">
                        {new Date(log.called_at).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination Footer */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-6 py-3 border-t border-slate-100 bg-slate-50/50 text-xs">
              <span className="text-slate-500">
                Page {page} of {totalPages}
              </span>
              <div className="flex items-center gap-2">
                <button
                  disabled={page <= 1}
                  onClick={() => setPage(p => Math.max(1, p - 1))}
                  className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-slate-600 disabled:opacity-50 hover:bg-slate-50"
                >
                  Previous
                </button>
                <button
                  disabled={page >= totalPages}
                  onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                  className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-slate-600 disabled:opacity-50 hover:bg-slate-50"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>
      ) : (
        /* Leaderboard & Employee Analytics Tab */
        <div className="space-y-6">
          <div className="flex bg-slate-100 rounded-xl p-1 gap-1 self-start w-fit">
            {(['me', ...(isManager ? ['team'] : []), ...(isAdmin ? ['all'] : [])] as ('me' | 'team' | 'all')[]).map(v => (
              <button
                key={v}
                onClick={() => setView(v)}
                className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
                  view === v ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                {v === 'me' ? 'My Analytics' : v === 'team' ? 'My Team' : 'All Staff'}
              </button>
            ))}
          </div>

          {view === 'me' && analytics && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <StatCard icon={PhoneCall} label="Total Calls" value={analytics.total_calls} color="#003A66" bg="#EFF6FF" />
              <StatCard icon={Phone} label="Answered" value={analytics.answered} sub={`${analytics.answer_rate}% answer rate`} color="#059669" bg="#F0FDF4" />
              <StatCard icon={PhoneMissed} label="Not Answered" value={analytics.not_answered} sub={`${analytics.missed} missed`} color="#DC2626" bg="#FEF2F2" />
              <StatCard icon={Users} label="Unique Leads" value={analytics.unique_leads_called} color="#7C3AED" bg="#F5F3FF" />
              <StatCard icon={Clock} label="Talk Time" value={formatDuration(analytics.total_talk_time_seconds)} color="#D97706" bg="#FFFBEB" />
              <StatCard icon={BarChart3} label="Avg Duration" value={formatDuration(analytics.avg_call_duration_seconds)} color="#0891B2" bg="#F0F9FF" />
              <StatCard icon={TrendingUp} label="Answer Rate" value={`${analytics.answer_rate}%`} color="#059669" bg="#F0FDF4" />
              <StatCard icon={Award} label="Score" value={analytics.answer_rate >= 70 ? 'Excellent' : 'Good'} color="#7C3AED" bg="#F5F3FF" />
            </div>
          )}

          {(view === 'team' || view === 'all') && (
            <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
              <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
                <h3 className="text-sm font-bold text-slate-900">Team Performance Ranking</h3>
                <Award className="w-5 h-5 text-amber-500" />
              </div>
              <div className="overflow-x-auto">
                <table className="table-crm w-full text-sm border-separate border-spacing-0">
                  <thead>
                    <tr className="bg-slate-50 border-b border-slate-200">
                      <th className="px-4 py-3 text-left text-xs font-bold text-slate-500 uppercase">#</th>
                      <th className="px-4 py-3 text-left text-xs font-bold text-slate-500 uppercase">Employee</th>
                      <th className="px-4 py-3 text-right text-xs font-bold text-slate-500 uppercase">Total Calls</th>
                      <th className="px-4 py-3 text-right text-xs font-bold text-slate-500 uppercase">Answered</th>
                      <th className="px-4 py-3 text-right text-xs font-bold text-slate-500 uppercase">Talk Time</th>
                      <th className="px-4 py-3 text-right text-xs font-bold text-slate-500 uppercase">Answer Rate</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {teamData.map((m, idx) => (
                      <tr key={m.user_id || idx} className="hover:bg-slate-50 transition-colors">
                        <td className="px-4 py-3 text-xs font-bold text-slate-500">{idx + 1}</td>
                        <td className="px-4 py-3 font-semibold text-slate-900">{m.name}</td>
                        <td className="px-4 py-3 text-right font-semibold text-slate-700">{m.total_calls}</td>
                        <td className="px-4 py-3 text-right text-emerald-600 font-bold">{m.answered}</td>
                        <td className="px-4 py-3 text-right text-slate-500">{formatDuration(m.total_talk_time_seconds)}</td>
                        <td className="px-4 py-3 text-right font-bold text-slate-700">{m.answer_rate}%</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Footer Info Notice */}
      <div className="flex items-start gap-3 bg-blue-50 border border-blue-200 rounded-xl p-4">
        <AlertCircle className="w-4 h-4 text-blue-500 shrink-0 mt-0.5" />
        <p className="text-xs text-blue-700">
          <strong>Sync Status:</strong> Call logs are synchronized automatically from Android sales devices via the ETaxwala mobile application.
        </p>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Link, Outlet, useLocation, useNavigate } from 'react-router-dom';
import {
  LayoutDashboard,
  Users,
  PhoneCall,
  ClipboardList,
  CheckCircle2,
  FileSpreadsheet,
  Building,
  BarChart3,
  UserCog,
  Briefcase,
  HelpCircle,
  FileCheck2,
  LogOut,
  Bell,
  Search,
  Menu,
  X,
  Shield,
  Layers,
  ChevronDown,
  ChevronRight,
  Sparkles,
  ExternalLink,
  Phone,
  Calendar,
  Settings,
  FolderLock,
  Headphones,
  Video,
  MonitorCheck,
  Command,
  Monitor,
  FolderKanban,
  FileText,
  Clock,
  Radio,
  Share2,
  Award,
  Globe,
  DollarSign,
  UserCheck,
  MessageSquare,
  MessageCircle,
  Target,
  Terminal,
  MapPin,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';
import { RoleType } from '@etaxwala/types';
import CommandPalette from './components/command-palette';
import NotificationCenter, { NotificationBadge } from './components/notification-center';
import { hasUserPermission } from './permissions';
import { ChatNotificationProvider, useChatNotification } from './context/chat-notification-context';

function CrmLayoutContent() {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({
    sales: true,
    operations: true,
    franchise: false,
    admin: false,
    desktop: false,
    opsReports: false,
    leadsSub: true,
    salesEmployee: true,
    quotationsSub: false,
    tasksSub: false,
  });
  const [cmdPaletteOpen, setCmdPaletteOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const bellRef = useRef<HTMLButtonElement>(null);
  const location = useLocation();
  const navigate = useNavigate();
  const { staffUser, activeRole, setStaffRole, logoutStaff } = useAuthStore();
  const { unreadChatCount, triggerTestWhatsAppNotification } = useChatNotification();
  const UNREAD_COUNT = 4;

  const toggleSection = (section: string) => {
    setOpenSections((prev) => ({ ...prev, [section]: !prev[section] }));
  };

  // Global Cmd+K / Ctrl+K shortcut
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setCmdPaletteOpen((prev) => !prev);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  const ALL_ROLE_OPTIONS: { role: RoleType; label: string; staffName: string }[] = [
    {
      role: RoleType.SUPER_ADMIN,
      label: 'Super Admin (All Access)',
      staffName: 'ETaxwala HQ Admin',
    },
    { role: RoleType.ADMIN, label: 'General Administrator', staffName: 'System Manager' },
    { role: RoleType.OPERATIONS_MANAGER, label: 'Operations Manager', staffName: 'Vaijnath Sir' },
    { role: RoleType.SALES_MANAGER, label: 'Sales Manager', staffName: 'Netra Divekar' },
    { role: RoleType.MARKETING_MANAGER, label: 'Marketing Manager', staffName: 'Growth Lead' },
    { role: RoleType.FRANCHISE_MANAGER, label: 'Franchise Manager', staffName: 'Kunal Patil' },
    {
      role: RoleType.SALES_EMPLOYEE,
      label: 'Sales Employee (Telecaller)',
      staffName: 'Priya Sharma',
    },
    {
      role: RoleType.OPERATIONS_EMPLOYEE,
      label: 'Operations Specialist',
      staffName: 'Sachin Mohan Vyavahare',
    },
    {
      role: RoleType.MARKETING_EMPLOYEE,
      label: 'Marketing Content & SEO',
      staffName: 'Content Specialist',
    },
    {
      role: RoleType.FRANCHISE_EMPLOYEE,
      label: 'Franchise Partner Desk',
      staffName: 'Field Partner',
    },
    { role: RoleType.CONSULTATION, label: 'CA / Tax Expert Workbench', staffName: 'CA Tax Expert' },
    { role: RoleType.OPERATIONS_ASSISTANT, label: 'QC & Document Reviewer', staffName: 'QC Lead' },
    {
      role: RoleType.SALES_ASSISTANT,
      label: 'Sales Assistant / Qualifier',
      staffName: 'Shreya Joshi',
    },
    { role: RoleType.HR, label: 'HR Manager (Workforce & Tracking)', staffName: 'HR Manager' },
    {
      role: RoleType.WEBSITE_MANAGER,
      label: 'Website & Sub-Brands Manager',
      staffName: 'Sub-Brands Lead',
    },
    { role: RoleType.STAFF, label: 'Staff / Client Support Desk', staffName: 'Support Executive' },
  ];

  const isSuperAdmin =
    activeRole === RoleType.SUPER_ADMIN ||
    staffUser?.role === RoleType.SUPER_ADMIN ||
    (Array.isArray(staffUser?.roles) && staffUser.roles.includes(RoleType.SUPER_ADMIN));

  const roleOptions =
    isSuperAdmin || !staffUser?.roles || staffUser.roles.length === 0
      ? ALL_ROLE_OPTIONS
      : ALL_ROLE_OPTIONS.filter((opt) => staffUser.roles!.includes(opt.role));

  const currentRoleInfo =
    ALL_ROLE_OPTIONS.find((r) => r.role === activeRole) || ALL_ROLE_OPTIONS[0];

  const displayStaffName =
    staffUser?.username || (staffUser as any)?.name || currentRoleInfo.staffName;

  const handleLogout = () => {
    logoutStaff();
    navigate('/crm/login');
  };

  const can = (permKey: string) => {
    return hasUserPermission(staffUser?.permissions, activeRole, permKey, staffUser?.roles);
  };

  const handleNavClick = () => {
    if (window.innerWidth < 768) {
      setSidebarOpen(false);
    }
  };

  // Role detection ΓÇö checks activeRole (handles both Super Admin switcher and actual user login)
  const isActiveRole = (roleType: RoleType | string) =>
    activeRole === roleType || activeRole === (roleType as string);

  const isAdmin =
    isSuperAdmin ||
    isActiveRole(RoleType.ADMIN) ||
    (!isSuperAdmin && (staffUser?.roles || []).includes(RoleType.ADMIN)) ||
    (!isSuperAdmin && (staffUser?.roleIds || []).includes(2));

  const isSalesManager =
    isSuperAdmin ||
    isActiveRole(RoleType.SALES_MANAGER) ||
    (!isSuperAdmin && (staffUser?.roles || []).includes(RoleType.SALES_MANAGER)) ||
    (!isSuperAdmin && (staffUser?.roleIds || []).includes(4));

  const isSalesEmployee =
    isActiveRole(RoleType.SALES_EMPLOYEE) ||
    (!isSuperAdmin && (staffUser?.roles || []).includes(RoleType.SALES_EMPLOYEE)) ||
    (!isSuperAdmin && (staffUser?.roleIds || []).includes(7));

  const isOpsManager =
    isSuperAdmin ||
    isActiveRole(RoleType.OPERATIONS_MANAGER) ||
    (!isSuperAdmin && (staffUser?.roles || []).includes(RoleType.OPERATIONS_MANAGER)) ||
    (!isSuperAdmin && (staffUser?.roleIds || []).includes(3));

  const isFranchiseManager =
    isSuperAdmin ||
    isActiveRole(RoleType.FRANCHISE_MANAGER) ||
    (!isSuperAdmin && (staffUser?.roles || []).includes(RoleType.FRANCHISE_MANAGER)) ||
    (!isSuperAdmin && (staffUser?.roleIds || []).includes(6));

  // Section visibility: Super Admin sees all main manager sections directly in sidebar
  const showOpsSection =
    (isSuperAdmin || isOpsManager) &&
    (can('operations:view') ||
      can('desktop_tracking:view') ||
      can('operations:employees') ||
      can('operations:customers') ||
      can('operations:tasks') ||
      can('accounts:view'));

  const showFranchiseSection =
    (isSuperAdmin || isFranchiseManager) &&
    (can('franchise:view') ||
      can('franchise:partners') ||
      can('franchise:inquiries') ||
      can('franchise:training'));

  const showSalesSection =
    (isSuperAdmin || isSalesManager) &&
    (isSuperAdmin ||
      can('sales:view') ||
      can('leads:view') ||
      can('quotations:view') ||
      can('tasks:view') ||
      can('workforce:view'));

  const showSalesEmployeeSection =
    isSalesEmployee && (can('leads:view') || can('quotations:view') || can('tasks:view'));

  const showAdminSection =
    isSuperAdmin ||
    isAdmin ||
