    try {
      await fetch(`${API_BASE}/v1/crm/leads/assign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ lead_ids: idsArray, assign_to_user_id: 1 }),
