                assignTo: assignStaff,
                isAssign: true,
                assignDate: new Date().toLocaleString(),
              }
            : l
        )
      );
      alert(`Assigned ${selectedIds.size} leads to ${assignStaff} and saved in database.`);
      setSelectedIds(new Set());
