        )
      );
      if (detailsModalLead) {
        setDetailsModalLead({
          ...detailsModalLead,
          status: editStatus,
          remarks: [newEntry, ...(detailsModalLead.remarks || [])],
        });
      }
      setEditRemark('');
      alert('Lead remark saved to database successfully!');
