    const firstService = servicesList[0] || DEFAULT_SERVICES[0];
    const newItem: QuotationItem = {
      id: `item-${Date.now()}`,
      isManual: false,
      serviceName: firstService.service_name,
      description:
        firstService.description || `${firstService.service_name} standard service package.`,
