import { useAuthStore } from '@/store/auth-store';

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

interface Applicant {
  id: string;
  name: string;
  email: string;
  phone: string;
  role: string;
  department: string;
  experience: string;
  linkedin?: string;
  expectedCtc?: string;
  noticePeriod?: string;
  resumeFileName?: string;
  resumeUrl?: string;
  status: 'new' | 'review' | 'shortlisted' | 'interview_scheduled' | 'offered' | 'rejected';
  interviewDate?: string;
  interviewType?: 'Telephonic' | 'Google Meet' | 'In-Person';
  rating?: number;
  notes?: string[];
  appliedAt: string;
}

export default function HrDashboard() {
  const staffToken = useAuthStore((s) => s.staffToken);
  const [activeTab, setActiveTab] = useState<'ats' | 'workforce' | 'accounts'>('ats');
  const [applicants, setApplicants] = useState<Applicant[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedApplicant, setSelectedApplicant] = useState<Applicant | null>(null);
  const [newNote, setNewNote] = useState('');
  const [interviewDateInput, setInterviewDateInput] = useState('');
  const [counts, setCounts] = useState({
    total: 0,
    new: 0,
    review: 0,
    shortlisted: 0,
    interview_scheduled: 0,
    offered: 0,
    rejected: 0,
  });

  const fetchApplicants = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE}/v1/hr/applicants`, {
        headers: staffToken ? { Authorization: `Bearer ${staffToken}` } : {},
      });
      const json = await res.json();
      if (json.success && json.data) {
        setApplicants(json.data.applicants);
        setCounts(json.data.counts);
      }
    } catch (err) {
      console.error('Failed to fetch applicants:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApplicants();
  }, [staffToken]);

  const handleUpdateStatus = async (
    id: string,
    newStatus: Applicant['status'],
    extra?: { interviewDate?: string; rating?: number; note?: string }
  ) => {
    try {
      const res = await fetch(`${API_BASE}/v1/hr/applicants/${id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          ...(staffToken ? { Authorization: `Bearer ${staffToken}` } : {}),
        },
        body: JSON.stringify({ status: newStatus, ...extra }),
      });
      const json = await res.json();
      if (json.success) {
        setApplicants((prev) => prev.map((app) => (app.id === id ? json.data : app)));
        if (selectedApplicant?.id === id) {
          setSelectedApplicant(json.data);
        }
      }
    } catch (err) {
      console.error('Failed to update status:', err);
    }
  };

  const handleAddNote = async (id: string) => {
    if (!newNote.trim()) return;
    try {
      const res = await fetch(`${API_BASE}/v1/hr/applicants/${id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          ...(staffToken ? { Authorization: `Bearer ${staffToken}` } : {}),
        },
        body: JSON.stringify({ note: newNote }),
      });
      const json = await res.json();
      if (json.success) {
        setApplicants((prev) => prev.map((app) => (app.id === id ? json.data : app)));
        setSelectedApplicant(json.data);
        setNewNote('');
      }
    } catch (err) {
      console.error('Failed to add note:', err);
    }
  };

  const filteredApplicants = applicants.filter((app) => {
    const matchesStatus = statusFilter === 'all' || app.status === statusFilter;
    const q = searchQuery.toLowerCase();
    const matchesSearch =
      !q ||
      app.name.toLowerCase().includes(q) ||
      app.email.toLowerCase().includes(q) ||
      app.role.toLowerCase().includes(q) ||
      app.phone.includes(q);
    return matchesStatus && matchesSearch;
