                      className={`inline-block text-[10px] font-bold px-2 py-0.5 rounded-full ${
                        inv.status.includes('Paid')
                          ? 'bg-emerald-50 text-emerald-700'
                          : 'bg-amber-50 text-amber-700'
                      }`}
                    >
                      {inv.status}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ CANDIDATE PROFILE DETAIL DRAWER / MODAL ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {selectedApplicant && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-slate-200">
            {/* Modal Header */}
            <div className="p-6 border-b border-slate-100 flex items-center justify-between sticky top-0 bg-white z-10">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 rounded-full bg-brand-navy text-white font-bold flex items-center justify-center text-sm">
                  {selectedApplicant.name.charAt(0)}
                </div>
                <div>
                  <h3 className="font-display font-bold text-lg text-slate-800">
                    {selectedApplicant.name}
                  </h3>
                  <p className="text-xs text-brand-navy font-semibold">{selectedApplicant.role}</p>
                </div>
              </div>
              <button
                onClick={() => setSelectedApplicant(null)}
                className="p-2 rounded-xl text-slate-400 hover:bg-slate-100 hover:text-slate-700 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Modal Body */}
            <div className="p-6 space-y-6 text-xs">
              {/* Status Badge & Stage Actions */}
              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div>
                  <p className="text-[10px] font-bold uppercase text-slate-400">Current Stage</p>
                  <div className="mt-1">{getStatusBadge(selectedApplicant.status)}</div>
                </div>

                <div className="flex flex-wrap items-center gap-1.5">
                  <button
                    onClick={() => handleUpdateStatus(selectedApplicant.id, 'shortlisted')}
                    className="px-2.5 py-1.5 rounded-lg bg-sky-50 text-sky-700 font-bold hover:bg-sky-100 transition-colors"
                  >
                    Shortlist
                  </button>
                  <button
                    onClick={() =>
                      handleUpdateStatus(selectedApplicant.id, 'interview_scheduled', {
                        interviewDate: 'Scheduled for Tomorrow 3 PM',
                      })
                    }
                    className="px-2.5 py-1.5 rounded-lg bg-blue-50 text-blue-700 font-bold hover:bg-blue-100 transition-colors"
                  >
                    Set Interview
                  </button>
                  <button
                    onClick={() => handleUpdateStatus(selectedApplicant.id, 'offered')}
                    className="px-2.5 py-1.5 rounded-lg bg-emerald-50 text-emerald-700 font-bold hover:bg-emerald-100 transition-colors"
                  >
                    Give Offer
                  </button>
                  <button
                    onClick={() => handleUpdateStatus(selectedApplicant.id, 'rejected')}
                    className="px-2.5 py-1.5 rounded-lg bg-rose-50 text-rose-700 font-bold hover:bg-rose-100 transition-colors"
                  >
                    Reject
                  </button>
                </div>
              </div>

              {/* Grid Information */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-slate-400 font-semibold">Phone Number</p>
                  <p className="font-bold text-slate-800 mt-0.5">{selectedApplicant.phone}</p>
                </div>
                <div>
                  <p className="text-slate-400 font-semibold">Email Address</p>
                  <p className="font-bold text-slate-800 mt-0.5">{selectedApplicant.email}</p>
                </div>
                <div>
                  <p className="text-slate-400 font-semibold">Experience</p>
                  <p className="font-bold text-slate-800 mt-0.5">{selectedApplicant.experience}</p>
                </div>
                <div>
                  <p className="text-slate-400 font-semibold">Expected CTC</p>
                  <p className="font-bold text-emerald-600 mt-0.5">
                    {selectedApplicant.expectedCtc || 'Not specified'}
                  </p>
                </div>
                {selectedApplicant.noticePeriod && (
                  <div>
                    <p className="text-slate-400 font-semibold">Notice Period</p>
                    <p className="font-bold text-slate-800 mt-0.5">
                      {selectedApplicant.noticePeriod}
                    </p>
                  </div>
                )}
                {selectedApplicant.linkedin && (
                  <div>
                    <p className="text-slate-400 font-semibold">Portfolio / Profile</p>
                    <a
                      href={selectedApplicant.linkedin}
                      target="_blank"
                      rel="noreferrer"
                      className="font-bold text-[#0084D1] hover:underline flex items-center gap-1 mt-0.5"
                    >
                      View Link <ExternalLink className="w-3 h-3" />
                    </a>
                  </div>
                )}
              </div>

              {/* Resume File */}
              {selectedApplicant.resumeUrl && (
                <div className="p-3 bg-blue-50/60 border border-blue-200 rounded-xl flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <FileText className="w-5 h-5 text-[#0084D1]" />
                    <div>
                      <p className="font-bold text-slate-800">Uploaded Resume Attachment</p>
                      <p className="text-[11px] text-slate-500">
                        {selectedApplicant.resumeFileName || 'resume.pdf'}
                      </p>
                    </div>
                  </div>
                  <a
                    href={`${API_BASE}${selectedApplicant.resumeUrl}`}
                    target="_blank"
                    rel="noreferrer"
                    className="px-3 py-1.5 rounded-xl btn-multicolor font-bold"
                  >
                    Download CV
                  </a>
                </div>
              )}

              {/* Notes & Feedback */}
              <div className="space-y-3">
                <p className="font-bold text-slate-800">HR & Interview Notes</p>
                <div className="space-y-2">
                  {selectedApplicant.notes && selectedApplicant.notes.length > 0 ? (
                    selectedApplicant.notes.map((n, i) => (
                      <div
                        key={i}
                        className="p-3 bg-slate-50 rounded-lg border border-slate-200 text-slate-700"
                      >
                        {n}
                      </div>
                    ))
                  ) : (
                    <p className="text-slate-400 italic">No interview notes recorded yet.</p>
                  )}
                </div>

                <div className="flex items-center gap-2 mt-2">
                  <input
                    type="text"
                    placeholder="Add interview assessment note..."
                    value={newNote}
                    onChange={(e) => setNewNote(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAddNote(selectedApplicant.id)}
                    className="flex-1 px-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#0084D1]/20 font-medium"
                  />
                  <button
                    onClick={() => handleAddNote(selectedApplicant.id)}
                    className="px-3.5 py-2 btn-multicolor rounded-lg font-bold transition-colors flex items-center gap-1"
                  >
                    <Send className="w-3.5 h-3.5" /> Save
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Code,
  Terminal,
  Cpu,
  Server,
  Video,
  FileText,
  Calendar,
  Layers,
  CheckCircle2,
  Clock,
  ExternalLink,
  Plus,
  Search,
  Sparkles,
  GitBranch,
  Shield,
  Activity,
  Send,
  X,
  Phone,
  Mail,
  DollarSign,
  AlertCircle,
  Copy,
  Check,
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

interface TechLead {
  id: string;
  clientName: string;
  companyName?: string;
  email: string;
  phone: string;
  projectType: string;
  budgetEstimate: string;
  timeline: string;
  requirements: string;
  status: 'new' | 'discovery_booked' | 'proposal_sent' | 'won' | 'lost';
  assignedEngineer: string;
  createdAt: string;
}

interface ClientMeeting {
  id: string;
  leadId?: string;
  clientName: string;
  meetingTitle: string;
  dateTime: string;
  durationMinutes: number;
  meetUrl: string;
  platform: string;
  status: 'scheduled' | 'in_progress' | 'completed' | 'rescheduled';
  attendees: string[];
  clientNotes?: string;
}

interface TechQuotation {
  id: string;
  quoteNumber: string;
  clientName: string;
  companyName?: string;
  clientEmail: string;
  projectTitle: string;
  techStack: string[];
  currency: 'INR' | 'USD';
  milestones: {
    title: string;
    description: string;
    percentage: number;
    amount: number;
    estimatedWeeks: number;
  }[];
  totalAmount: number;
  validUntil: string;
  status: 'draft' | 'sent' | 'client_reviewed' | 'accepted' | 'rejected';
}

interface TechProject {
  id: string;
  title: string;
  clientName: string;
  leadEngineer: string;
  stage: string;
  progressPercent: number;
  techStack: string[];
  repoUrl?: string;
  stagingUrl?: string;
  deadline: string;
  status: 'on_track' | 'needs_review' | 'blocked' | 'delivered';
}

interface TelemetryData {
  server: {
    status: string;
    uptime: string;
    cpuCount: number;
    nodeVersion: string;
    memory: { rssMb: number; heapUsedMb: number; heapTotalMb: number };
  };
  services: {
    database: { status: string; engine: string; poolActive: number; latencyMs: number };
    redis: { status: string; latencyMs: number };
    websockets: { status: string; connectedClients: number; activeRooms: number };
  };
  endpointsTraffic: {
    path: string;
    requestsToday: number;
    avgLatency: string;
    successRate: string;
  }[];
}

export default function ItCommandDashboard() {
  const [activeTab, setActiveTab] = useState<'leads' | 'meetings' | 'quotes' | 'telemetry'>(
    'leads'
  );
  const [leads, setLeads] = useState<TechLead[]>([]);
  const [meetings, setMeetings] = useState<ClientMeeting[]>([]);
  const [quotations, setQuotations] = useState<TechQuotation[]>([]);
  const [projects, setProjects] = useState<TechProject[]>([]);
  const [telemetry, setTelemetry] = useState<TelemetryData | null>(null);
  const [loading, setLoading] = useState(true);
  const [copiedUrl, setCopiedUrl] = useState<string | null>(null);

  // Modals
  const [isMeetingModalOpen, setIsMeetingModalOpen] = useState(false);
  const [isQuoteModalOpen, setIsQuoteModalOpen] = useState(false);

  // Form states for meeting
  const [meetClientName, setMeetClientName] = useState('');
  const [meetTitle, setMeetTitle] = useState('');
  const [meetDateTime, setMeetDateTime] = useState('');
  const [meetNotes, setMeetNotes] = useState('');

  // Form states for quote
  const [quoteClient, setQuoteClient] = useState('');
  const [quoteEmail, setQuoteEmail] = useState('');
  const [quoteProject, setQuoteProject] = useState('');
  const [quoteBudget, setQuoteBudget] = useState(450000);
  const [quoteStack, setQuoteStack] = useState('React, TypeScript, Node.js, PostgreSQL');

  const staffToken = useAuthStore((s) => s.staffToken);
  const getHeaders = () => ({
    'Content-Type': 'application/json',
    Authorization: `Bearer ${staffToken || 'demo-staff-token'}`,
  });

  const fetchAll = async () => {
    try {
      setLoading(true);
      const headers = getHeaders();
      const [leadsRes, meetingsRes, quotesRes, projRes, teleRes] = await Promise.all([
        fetch(`${API_BASE}/v1/it/leads`, { headers }),
        fetch(`${API_BASE}/v1/it/meetings`, { headers }),
        fetch(`${API_BASE}/v1/it/quotations`, { headers }),
        fetch(`${API_BASE}/v1/it/projects`, { headers }),
        fetch(`${API_BASE}/v1/it/telemetry`, { headers }),
      ]);

      const [leadsJson, meetingsJson, quotesJson, projJson, teleJson] = await Promise.all([
        leadsRes.json(),
        meetingsRes.json(),
        quotesRes.json(),
        projRes.json(),
        teleRes.json(),
      ]);

      if (leadsJson.success) setLeads(leadsJson.data.leads);
      if (meetingsJson.success) setMeetings(meetingsJson.data.meetings);
      if (quotesJson.success) setQuotations(quotesJson.data.quotations);
      if (projJson.success) setProjects(projJson.data.projects);
      if (teleJson.success) setTelemetry(teleJson.data);
    } catch (err) {
      console.error('Failed to load IT dashboard data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, []);

  const handleCopyMeet = (url: string) => {
    navigator.clipboard.writeText(url);
    setCopiedUrl(url);
    setTimeout(() => setCopiedUrl(null), 2000);
  };

  const handleCreateMeeting = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!meetClientName || !meetTitle) return;

    try {
      const res = await fetch(`${API_BASE}/v1/it/meetings`, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify({
          clientName: meetClientName,
          meetingTitle: meetTitle,
          dateTime: meetDateTime || 'Tomorrow, 4:00 PM',
          clientNotes: meetNotes,
        }),
      });

      const json = await res.json();
      if (json.success) {
        setMeetings([json.data, ...meetings]);
        setIsMeetingModalOpen(false);
        setMeetClientName('');
        setMeetTitle('');
        setMeetNotes('');
      }
    } catch (err) {
      console.error('Failed to schedule meeting:', err);
    }
  };

  const handleCreateQuote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!quoteClient || !quoteProject) return;

    try {
      const res = await fetch(`${API_BASE}/v1/it/quotations`, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify({
          clientName: quoteClient,
          clientEmail: quoteEmail || 'client@business.com',
          projectTitle: quoteProject,
          techStack: quoteStack.split(',').map((s) => s.trim()),
          totalAmount: quoteBudget,
        }),
      });

      const json = await res.json();
      if (json.success) {
        setQuotations([json.data, ...quotations]);
        setIsQuoteModalOpen(false);
        setQuoteClient('');
        setQuoteEmail('');
        setQuoteProject('');
      }
    } catch (err) {
      console.error('Failed to create quotation:', err);
    }
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto pb-12">
      {/* Top Banner with Engineering Theme */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-gradient-to-r from-slate-900 via-brand-navy to-slate-900 p-6 rounded-2xl text-white shadow-xl">
        <div>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-blue-500/20 border border-blue-400/30 flex items-center justify-center text-blue-400">
              <Terminal className="w-5 h-5" />
            </div>
            <div>
              <h1 className="text-2xl font-display font-bold">IT & Solutions Command Center</h1>
              <p className="text-xs text-blue-200/70 mt-0.5">
                Internal Tech Team Workspace ΓÇó Client Discovery Calls ΓÇó Technical Proposals &
                Quotations ΓÇó Telemetry
              </p>
            </div>
          </div>
        </div>

        {/* Tab Switcher */}
        <div className="flex items-center bg-white/10 backdrop-blur-md p-1 rounded-xl border border-white/10 text-xs font-bold">
          <button
            onClick={() => setActiveTab('leads')}
            className={`px-3.5 py-2 rounded-lg transition-all flex items-center gap-1.5 ${
              activeTab === 'leads'
                ? 'bg-[#0084D1] text-white shadow-sm'
                : 'text-slate-300 hover:text-white'
            }`}
          >
            <Layers className="w-3.5 h-3.5" />
            Inbound Leads ({leads.length})
          </button>
          <button
            onClick={() => setActiveTab('meetings')}
            className={`px-3.5 py-2 rounded-lg transition-all flex items-center gap-1.5 ${
              activeTab === 'meetings'
                ? 'bg-[#0084D1] text-white shadow-sm'
                : 'text-slate-300 hover:text-white'
            }`}
          >
            <Video className="w-3.5 h-3.5" />
            Discovery Calls ({meetings.length})
          </button>
          <button
            onClick={() => setActiveTab('quotes')}
            className={`px-3.5 py-2 rounded-lg transition-all flex items-center gap-1.5 ${
              activeTab === 'quotes'
                ? 'bg-[#0084D1] text-white shadow-sm'
                : 'text-slate-300 hover:text-white'
            }`}
          >
            <FileText className="w-3.5 h-3.5" />
            Quotations ({quotations.length})
          </button>
          <button
            onClick={() => setActiveTab('telemetry')}
            className={`px-3.5 py-2 rounded-lg transition-all flex items-center gap-1.5 ${
              activeTab === 'telemetry'
                ? 'bg-[#0084D1] text-white shadow-sm'
                : 'text-slate-300 hover:text-white'
            }`}
          >
            <Activity className="w-3.5 h-3.5" />
            System Health
          </button>
        </div>
      </div>

      {/* KPI Overview */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-500 uppercase">Tech Pipeline</p>
          <p className="font-display font-bold text-2xl text-brand-navy mt-1">Γé╣19.5 Lakh</p>
          <p className="text-[11px] text-emerald-600 font-semibold mt-1">
            3 Discovery Calls Active
          </p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-500 uppercase">Quotations Sent</p>
          <p className="font-display font-bold text-2xl text-purple-700 mt-1">Γé╣5.0 Lakh</p>
          <p className="text-[11px] text-slate-400 mt-1">FinPulse Logistics Fleet System</p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-500 uppercase">Active Projects</p>
          <p className="font-display font-bold text-2xl text-[#0084D1] mt-1">
            {projects.length} In Progress
          </p>
          <p className="text-[11px] text-slate-400 mt-1">Apex Commodities + ETaxwala 2.0</p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-500 uppercase">API Health & Uptime</p>
          <p className="font-display font-bold text-2xl text-emerald-600 mt-1">99.9% Uptime</p>
          <p className="text-[11px] text-emerald-600 font-semibold mt-1">
            PostgreSQL & WebSockets Live
          </p>
        </div>
      </div>

      {/* ΓöÇΓöÇΓöÇ TAB 1: INBOUND TECH LEADS ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {activeTab === 'leads' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="font-display font-bold text-lg text-slate-800">
                Inbound Software & Tech Inquiries
              </h2>
              <p className="text-xs text-slate-400 mt-0.5">
                Prospective clients appointing ETaxwala IT team for custom CRM, SaaS, or Mobile Apps
              </p>
            </div>
            <button
              onClick={() => setIsMeetingModalOpen(true)}
              className="px-4 py-2 btn-multicolor text-xs font-bold rounded-xl transition-colors flex items-center gap-1.5"
            >
              <Plus className="w-4 h-4" /> Schedule Discovery Call
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
            {leads.map((lead) => (
              <div
                key={lead.id}
                className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all flex flex-col justify-between"
              >
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-bold px-2 py-0.5 bg-blue-50 text-[#0084D1] rounded-full">
                      {lead.projectType}
                    </span>
                    <span
                      className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                        lead.status === 'won'
                          ? 'bg-emerald-50 text-emerald-700'
                          : lead.status === 'discovery_booked'
                            ? 'bg-purple-50 text-purple-700'
                            : 'bg-slate-100 text-slate-700'
                      }`}
                    >
                      {lead.status.replace('_', ' ').toUpperCase()}
                    </span>
                  </div>

                  <h3 className="font-bold text-base text-slate-900">{lead.clientName}</h3>
                  {lead.companyName && (
                    <p className="text-xs font-semibold text-slate-500 mt-0.5">
                      {lead.companyName}
                    </p>
                  )}

                  <div className="mt-3 p-3 bg-slate-50 rounded-xl border border-slate-100 text-xs text-slate-600">
                    <p className="font-medium line-clamp-2">{lead.requirements}</p>
                  </div>

                  <div className="grid grid-cols-2 gap-2 mt-4 text-[11px]">
                    <div>
                      <p className="text-slate-400">Budget Range</p>
                      <p className="font-bold text-emerald-600">{lead.budgetEstimate}</p>
                    </div>
                    <div>
                      <p className="text-slate-400">Timeline</p>
                      <p className="font-bold text-slate-700">{lead.timeline}</p>
                    </div>
                  </div>
                </div>

                <div className="pt-4 mt-4 border-t border-slate-100 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <a
                      href={`tel:${lead.phone}`}
                      className="p-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                      title={lead.phone}
                    >
                      <Phone className="w-3.5 h-3.5" />
                    </a>
                    <a
                      href={`mailto:${lead.email}`}
                      className="p-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                      title={lead.email}
                    >
                      <Mail className="w-3.5 h-3.5" />
                    </a>
                  </div>

                  <button
                    onClick={() => {
                      setMeetClientName(lead.clientName);
                      setMeetTitle(`Discovery Call: ${lead.projectType}`);
                      setMeetNotes(lead.requirements);
                      setIsMeetingModalOpen(true);
                    }}
                    className="px-3 py-1.5 rounded-xl btn-multicolor text-xs font-bold flex items-center gap-1"
                  >
                    <Video className="w-3 h-3" /> Book Meet
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

