                  <th className="p-3">Customer Name</th>
                  <th className="p-3">Contact</th>
                  <th className="p-3">Total Amount</th>
                  <th className="p-3">Paid Amount</th>
                  <th className="p-3">Unpaid Balance</th>
                  <th className="p-3">Comments</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {feesReport.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="p-6 text-center text-slate-400">
                      No EMI fees report records found.
                    </td>
                  </tr>
                ) : (
                  feesReport.map((row) => (
                    <tr key={row.emi_id} className="hover:bg-slate-50">
                      <td className="p-3 font-bold text-slate-900">{row.customer_name}</td>
                      <td className="p-3 text-slate-600">{row.customer_phone || 'ΓÇö'}</td>
                      <td className="p-3 font-semibold text-slate-800">{formatCurrency(row.emi_total_amount)}</td>
                      <td className="p-3 font-semibold text-emerald-700">{formatCurrency(row.emi_paid_amount)}</td>
                      <td className="p-3 font-semibold text-rose-700">{formatCurrency(row.emi_unpaid_amount)}</td>
                      <td className="p-3 text-slate-500 truncate max-w-xs">{row.emi_comment || 'ΓÇö'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* MODAL: CLOSE TICKET */}
      {ticketToClose && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-xs p-4">
          <div className="bg-white w-full max-w-md rounded-2xl border border-slate-200 shadow-2xl p-6 space-y-4">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <h3 className="font-display font-bold text-base text-slate-900">Close Support Ticket</h3>
              <button onClick={() => setTicketToClose(null)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCloseTicketSubmit} className="space-y-4">
              <div>
                <p className="text-xs text-slate-500 mb-1">Customer Query:</p>
                <p className="text-xs font-medium text-slate-800 bg-slate-50 p-2.5 rounded-lg border border-slate-200">
                  {ticketToClose.ticket_msg}
                </p>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">Response / Resolution Answer:</label>
                <textarea
                  required
                  rows={4}
                  value={ticketAnswerInput}
                  onChange={(e) => setTicketAnswerInput(e.target.value)}
                  placeholder="Write support query response or action taken..."
                  className="w-full text-xs p-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none"
                />
              </div>

              <div className="flex justify-end gap-2 pt-2 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setTicketToClose(null)}
                  className="btn btn-outline btn-sm text-xs"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={closingTicket}
                  className="btn btn-primary btn-sm text-xs"
                >
                  {closingTicket ? 'Closing...' : 'Close Ticket'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL: GENERATE COUPON CODE (Ported from PHP generateCoupon Modal) */}
      {isCouponModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-xs p-4">
          <div className="bg-white w-full max-w-lg rounded-2xl border border-slate-200 shadow-2xl p-6 space-y-4">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <h3 className="font-display font-bold text-lg text-slate-900">Create New Coupon Code</h3>
              <button onClick={() => setIsCouponModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            {couponError && (
              <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-700">
                {couponError}
              </div>
            )}

            <form onSubmit={handleCreateCoupon} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Coupon Type</label>
                  <select
                    value={couponForm.coupon_type}
                    onChange={(e) => setCouponForm({ ...couponForm, coupon_type: Number(e.target.value) })}
                    className="w-full text-xs p-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none"
                  >
                    <option value={0}>Amount Wise (Γé╣ Flat Off)</option>
                    <option value={1}>Percentage Wise (% Off)</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Coupon Name / Code</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. DIWALI500"
                    value={couponForm.coupon_name}
                    onChange={(e) => {
                      const val = e.target.value.toUpperCase();
                      setCouponForm({ ...couponForm, coupon_name: val });
                      handleCheckCouponName(val);
                    }}
                    className="w-full text-xs p-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none uppercase font-mono"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Discount Value</label>
                  <input
                    type="number"
                    required
                    placeholder={couponForm.coupon_type === 1 ? 'Discount % (e.g. 15)' : 'Discount Γé╣ (e.g. 500)'}
                    value={couponForm.coupon_discount}
                    onChange={(e) => setCouponForm({ ...couponForm, coupon_discount: e.target.value })}
                    className="w-full text-xs p-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">Validity Date</label>
                  <input
                    type="date"
                    required
                    value={couponForm.coupon_validity}
                    onChange={(e) => setCouponForm({ ...couponForm, coupon_validity: e.target.value })}
                    className="w-full text-xs p-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none"
                  />
                </div>

                <div className="sm:col-span-2">
                  <label className="block text-xs font-bold text-slate-700 mb-1">Number of Uses Allowed</label>
                  <input
                    type="number"
                    required
                    min={1}
                    value={couponForm.coupon_uses}
                    onChange={(e) => setCouponForm({ ...couponForm, coupon_uses: e.target.value })}
                    className="w-full text-xs p-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-brand-navy focus:outline-none"
                  />
                </div>
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setIsCouponModalOpen(false)}
                  className="btn btn-outline btn-sm text-xs"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={creatingCoupon || !!couponError}
                  className="btn btn-primary btn-sm text-xs"
                >
                  {creatingCoupon ? 'Creating...' : 'Create Coupon Code'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
