    1: '#003A66',
    2: '#004d87',
    3: '#7C3AED',
    4: '#059669',
    5: '#DB2777',
    6: '#0891B2',
    7: '#10B981',
    8: '#8B5CF6',
    9: '#E11D48',
    10: '#0E7490',
    11: '#D97706',
    12: '#DC2626',
    13: '#047857',
    14: '#4F46E5',
    15: '#16A34A',
