      )}

      <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-3 relative z-10">
        <div className="flex items-center gap-3">
          <span className="flex h-2.5 w-2.5 shrink-0 relative">
            <span
