          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-4 shrink-0">
          <div className="flex items-center gap-1.5 sm:gap-2">
            {[
              { val: effectiveDays, label: 'Days' },
              { val: timeLeft.hours, label: 'Hrs' },
