  const directService = useMemo(
    () => (categorySlug ? getServiceBySlug(categorySlug) : null),
    [categorySlug]
  );
  if (directService) {
    const catSlug = directService.category
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');
    return <Navigate to={`/services/${catSlug}/${directService.slug}`} replace />;
  }

