                        <ul className="space-y-1.5 text-xs text-slate-500">
                          {s.inclusions.slice(0, 3).map((inc, i) => (
                            <li key={i} className="flex items-start gap-2 truncate">
                              <span className="w-1.5 h-1.5 rounded-full bg-[#7C3AED] mt-1.5 shrink-0" />
                              <span className="truncate">{inc}</span>
                            </li>
                          ))}
                        </ul>
                      </div>

                      <div className="mt-6 pt-4 border-t border-[#EAE6DD] flex items-center justify-between">
                        <div>
                          <span className="text-[10px] text-slate-400 font-semibold uppercase tracking-wider block">
                            Pricing
                          </span>
                          <span className="text-xs font-bold text-slate-800">Custom Quote</span>
                        </div>

                        <button
                          type="button"
                          onClick={() => setSelectedEnquiryService(s.name)}
                          aria-label={`Book free CA call for ${s.name}`}
                          className="group px-4 py-2 rounded-xl btn-multicolor text-xs font-extrabold shadow-xs hover:shadow-md transition-all cursor-pointer inline-flex items-center"
                        >
                          <span className="relative z-10 text-slate-900 font-extrabold flex items-center gap-1.5">
                            <span>Book Free CA Call</span>
                            <ArrowRight className="w-3.5 h-3.5 text-slate-700 transition-transform duration-200 group-hover:translate-x-1" />
                          </span>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </main>
          </div>
        </div>
      </section>

      {/* Signature Multicolour Outline CTA Banner */}
      <CtaBanner
        title="Can't find the exact service you're looking for?"
        subtitle="Speak directly with our senior Chartered Accountants and Legal Consultants. We handle customized corporate and taxation cases nationwide."
        primaryButtonText="Book Free Consultation"
        primaryButtonLink="/appointment"
        secondaryButtonText="Call Helpline: 080-6902-9999"
        secondaryIsPhone={true}
        phoneNumber="080-6902-9999"
      />

      <QuickEnquiryModal
        isOpen={!!selectedEnquiryService}
        onClose={() => setSelectedEnquiryService(null)}
        serviceTitle={selectedEnquiryService || ''}
      />
    </>
  );
}

import React, { useState } from 'react';
import {
  FolderLock,
  Upload,
  Download,
  FileCheck,
  Clock,
  AlertCircle,
  Trash2,
  Eye,
  Plus,
  ShieldCheck,
} from 'lucide-react';

export default function ClientDocumentsPage() {
  const [activeTab, setActiveTab] = useState('all');
  const [uploadSuccess, setUploadSuccess] = useState(false);
  const [docs, setDocs] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);

  React.useEffect(() => {
    fetch('/v1/customer/documents')
      .then((r) => r.json())
      .then((d) => {
        if (d?.success && Array.isArray(d.data)) setDocs(d.data);
      })
      .catch(() => {});
  }, []);

  const documentList =
    docs.length > 0
      ? docs
      : [
          {
            id: 1,
            title: 'PAN Card (Director 1)',
            category: 'KYC',
            type: 'PDF',
            size: '850 KB',
            date: '10 Aug 2026',
            status: 'VERIFIED',
            fileName: 'director1_pan.pdf',
          },
          {
            id: 2,
            title: 'Aadhaar Card (Director 1)',
            category: 'KYC',
            type: 'PDF',
            size: '1.2 MB',
            date: '10 Aug 2026',
            status: 'VERIFIED',
            fileName: 'director1_aadhaar.pdf',
          },
          {
            id: 3,
            title: 'Registered Office Electricity Bill',
            category: 'Business Proof',
            type: 'PDF',
            size: '2.4 MB',
            date: '12 Aug 2026',
            status: 'VERIFIED',
            fileName: 'office_noc_elec.pdf',
          },
          {
            id: 4,
            title: 'Approved RUN Name Reservation Letter',
            category: 'Deliverable',
            type: 'PDF',
            size: '320 KB',
            date: '14 Aug 2026',
            status: 'ISSUED',
            fileName: 'CRC_Name_Approval.pdf',
            isCertificate: true,
          },
        ];

  const filteredDocs =
    activeTab === 'all'
      ? documentList
      : activeTab === 'kyc'
        ? documentList.filter((d) => d.category === 'KYC' || d.category?.includes('Proof'))
        : activeTab === 'certificates'
          ? documentList.filter((d) => d.isCertificate || d.category === 'Deliverable')
          : documentList.filter((d) => d.status === 'PENDING_UPLOAD');

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('document', file);
    formData.append('title', file.name.replace(/\.[^/.]+$/, ''));

    try {
      const res = await fetch('/v1/customer/documents/upload', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      if (data?.success && data.document) {
        setDocs((prev) => [data.document, ...prev]);
        setUploadSuccess(true);
        setTimeout(() => setUploadSuccess(false), 4000);
      }
    } catch {
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-display font-bold text-brand-navy">
              Secure Document Vault
            </h1>
            <span className="badge badge-gold">256-Bit Encrypted</span>
          </div>
          <p className="text-xs text-slate-500 mt-1">
            End-to-end encrypted storage for your company incorporation certificates, DSC keys, KYC
            proofs & ROC filings.
          </p>
        </div>

        <label className="cursor-pointer">
          <input type="file" className="hidden" onChange={handleUpload} disabled={isUploading} />
          <button className="btn btn-primary btn-sm" disabled={isUploading}>
            <Upload className="w-3.5 h-3.5" /> {isUploading ? 'Uploading...' : 'Upload Document'}
          </button>
        </label>
      </div>

      {uploadSuccess && (
        <div className="p-4 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-800 text-xs font-semibold flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-emerald-600" /> Document uploaded successfully and
          sent to your CA verification specialist!
        </div>
      )}

      {/* Tabs */}
      <div className="flex flex-wrap gap-2 p-1.5 bg-white rounded-2xl border border-[#EAE6DD] shadow-xs w-fit">
        {[
          { id: 'all', label: 'All Documents', count: documentList.length },
          { id: 'kyc', label: 'KYC & Proofs', count: 4 },
          { id: 'certificates', label: 'Certificates & Deliverables', count: 2 },
          { id: 'pending', label: 'Pending Upload', count: 1 },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
              activeTab === tab.id
                ? 'btn-multicolor text-white shadow-xs'
                : 'text-slate-600 hover:bg-[#FAF9F5]'
            }`}
          >
            <span>{tab.label}</span>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${
                activeTab === tab.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-600'
              }`}
            >
              {tab.count}
            </span>
          </button>
        ))}
      </div>

      {/* Grid of Documents */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredDocs.map((doc) => (
          <div
            key={doc.id}
            className={`bg-[#FFFDF9] p-5 rounded-2xl border flex flex-col justify-between transition-all shadow-xs ${
              doc.isActionRequired
                ? 'border-amber-300 bg-amber-50/20'
                : 'border-[#EAE6DD] hover:shadow-md hover:border-[#7C3AED]/30'
            }`}
          >
            <div>
              <div className="flex items-center justify-between gap-2 mb-3">
                <span
                  className={`badge ${
                    doc.status === 'VERIFIED' || doc.status === 'ISSUED'
                      ? 'badge-green'
                      : doc.status === 'PENDING_UPLOAD'
                        ? 'badge-gold'
                        : 'badge-navy'
                  }`}
                >
                  {doc.status.replace('_', ' ')}
                </span>
                <span className="text-[11px] font-semibold text-slate-400">{doc.category}</span>
              </div>

              <h4 className="font-bold text-sm text-slate-900 line-clamp-2">{doc.title}</h4>

              <div className="mt-3 space-y-1 text-xs text-slate-500">
                {doc.fileName ? (
                  <p className="truncate font-mono text-[11px] text-[#0084D1] font-semibold">
                    ≡ƒôä {doc.fileName}
                  </p>
                ) : null}
                <p>Size: {doc.size}</p>
                <p>Updated: {doc.uploadedAt}</p>
              </div>
            </div>

            <div className="mt-5 pt-3 border-t border-[#EAE6DD] flex items-center justify-between gap-2">
              {doc.status === 'PENDING_UPLOAD' ? (
                <label className="w-full cursor-pointer">
                  <input type="file" className="hidden" onChange={handleUpload} />
                  <button className="btn-multicolor btn-sm w-full text-xs cursor-pointer">
                    <span className="relative z-10 flex items-center justify-center gap-1.5">
                      <Upload className="w-3.5 h-3.5" /> Upload Now
                    </span>
                  </button>
                </label>
              ) : (
                <>
                  <button className="btn-outline-multicolor btn-sm text-xs cursor-pointer">
                    <Eye className="w-3 h-3" /> Preview
                  </button>
                  <button className="btn-outline-multicolor btn-sm text-xs cursor-pointer">
                    <Download className="w-3.5 h-3.5 text-[#0084D1]" /> Download
                  </button>
                </>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  Mail,
  Phone,
  Lock,
  ArrowLeft,
  CheckCircle2,
  KeyRound,
  Loader2,
  ShieldCheck,
  Eye,
  EyeOff,
} from 'lucide-react';

export default function ClientForgotPasswordPage() {
  const [step, setStep] = useState<'request' | 'verify' | 'reset' | 'done'>('request');
  const [identifier, setIdentifier] = useState('');
  const [otp, setOtp] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSendOtp = (e: React.FormEvent) => {
    e.preventDefault();
    if (!identifier.trim()) {
      setError('Please enter your registered email or mobile number');
      return;
    }
    setError('');
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStep('verify');
    }, 600);
  };

  const handleVerifyOtp = (e: React.FormEvent) => {
    e.preventDefault();
    if (otp.length < 4) {
      setError('Please enter the 4 or 6 digit OTP sent to your phone/email');
      return;
    }
    setError('');
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStep('reset');
    }, 500);
  };

  const handleResetPassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }
    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    setError('');
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setStep('done');
    }, 600);
  };

  return (
    <div className="min-h-screen bg-[#FFFDF9] flex items-center justify-center p-4 font-sans">
      <div className="w-full max-w-lg space-y-6">
        {/* Brand */}
        <div className="text-center space-y-2">
          <Link to="/" className="inline-flex items-center gap-2.5">
            <img src="/logo_black.png" alt="ETaxwala" className="h-10 w-auto" />
          </Link>
          <div>
            <h1 className="text-2xl font-bold text-slate-900 mt-2">Reset Your Password</h1>
            <p className="text-xs text-slate-500 max-w-xs mx-auto mt-1">
              Verify your identity to regain access to your ETaxwala client vault.
            </p>
          </div>
        </div>

        {/* Card */}
        <div className="bg-white p-6 sm:p-8 rounded-3xl border border-[#EAE6DD] shadow-sm">
          {step === 'request' && (
            <form onSubmit={handleSendOtp} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Registered Email or Phone Number *
                </label>
                <div className="relative">
                  <Mail className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={identifier}
                    onChange={(e) => setIdentifier(e.target.value)}
                    placeholder="e.g. client@company.com or 9876543210"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                    required
                  />
                </div>
              </div>

              {error && <p className="text-xs text-rose-500">{error}</p>}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3.5 rounded-xl btn-multicolor text-white font-bold text-xs shadow-md flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 whitespace-nowrap shrink-0"
              >
                <span className="relative z-10 flex items-center justify-center gap-2 whitespace-nowrap">
                  {isLoading ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    'Send Verification OTP'
                  )}
                </span>
              </button>
            </form>
          )}

          {step === 'verify' && (
            <form onSubmit={handleVerifyOtp} className="space-y-4">
              <div className="p-3 bg-blue-50 border border-blue-200 rounded-xl text-xs text-blue-700">
                OTP has been dispatched to <strong>{identifier}</strong>.
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Enter 6-Digit OTP *
                </label>
                <div className="relative">
                  <KeyRound className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={otp}
                    onChange={(e) => setOtp(e.target.value)}
                    placeholder="123456"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm font-mono tracking-widest focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                    required
                  />
                </div>
              </div>

              {error && <p className="text-xs text-rose-500">{error}</p>}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3.5 rounded-xl btn-multicolor text-white font-bold text-xs shadow-md flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 whitespace-nowrap shrink-0"
              >
                <span className="relative z-10 flex items-center justify-center gap-2 whitespace-nowrap">
                  {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Verify Code'}
                </span>
              </button>
            </form>
          )}

          {step === 'reset' && (
            <form onSubmit={handleResetPassword} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  New Password *
                </label>
                <div className="relative">
                  <Lock className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="Min 6 characters"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-10 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 transition-colors cursor-pointer"
                    title={showPassword ? 'Hide Password' : 'Show Password'}
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Confirm New Password *
                </label>
                <div className="relative">
                  <Lock className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="Re-enter password"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-10 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 transition-colors cursor-pointer"
                    title={showPassword ? 'Hide Password' : 'Show Password'}
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              {error && <p className="text-xs text-rose-500">{error}</p>}

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3.5 rounded-xl btn-multicolor text-white font-bold text-xs shadow-md flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 whitespace-nowrap shrink-0"
              >
                <span className="relative z-10 flex items-center justify-center gap-2">
                  {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Set New Password'}
                </span>
              </button>
            </form>
          )}

          {step === 'done' && (
            <div className="py-6 text-center space-y-3">
              <div className="w-14 h-14 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center mx-auto">
                <CheckCircle2 className="w-8 h-8" />
              </div>
              <h3 className="text-lg font-bold text-slate-900">Password Reset Complete!</h3>
              <p className="text-xs text-slate-500">
                You can now log in securely with your updated password.
              </p>
              <Link
                to="/portal/login"
                className="inline-block mt-2 px-6 py-2.5 rounded-xl btn-multicolor text-white font-bold text-xs shadow-md"
              >
                <span>Go to Sign In</span>
              </Link>
            </div>
          )}

          <div className="mt-6 pt-4 border-t border-[#EAE6DD] text-center">
            <Link
              to="/portal/login"
              className="inline-flex items-center gap-1.5 text-xs text-slate-500 hover:text-[#0084D1] font-semibold"
            >
              <ArrowLeft className="w-3.5 h-3.5" /> Back to Login
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  User, Mail, Phone, Building, MapPin, Lock,
  Camera, CheckCircle2, ShieldCheck, KeyRound, Loader2
} from 'lucide-react';
import { useAuthStore } from '@/store/auth-store';

const profileSchema = z.object({
  name: z.string().min(1, 'Full name required'),
  business: z.string().optional(),
  email: z.string().email('Valid email required'),
  contact: z.string().min(10, '10-digit contact required'),
  city: z.string().min(1, 'City required'),
  state: z.string().min(1, 'State required'),
});

const passwordSchema = z.object({
  currentPassword: z.string().min(6, 'Current password required'),
  newPassword: z.string().min(6, 'New password must be at least 6 characters'),
  confirmPassword: z.string().min(6, 'Confirm password required'),
}).refine((data) => data.newPassword === data.confirmPassword, {
  message: 'Passwords do not match',
  path: ['confirmPassword'],
});

type ProfileData = z.infer<typeof profileSchema>;
type PasswordData = z.infer<typeof passwordSchema>;

export default function ClientProfilePage() {
  const { customer, loginCustomer, customerToken } = useAuthStore();
  const [profileSuccess, setProfileSuccess] = useState(false);
  const [passwordSuccess, setPasswordSuccess] = useState(false);
  const [passwordError, setPasswordError] = useState('');

  const {
    register: regProfile,
    handleSubmit: handleProfileSubmit,
    formState: { errors: profileErrors, isSubmitting: isProfileSubmitting },
  } = useForm<ProfileData>({
    resolver: zodResolver(profileSchema),
    defaultValues: {
      name: customer?.name || '',
      business: customer?.business || '',
      email: customer?.email || '',
      contact: customer?.contact || '',
      city: customer?.city || 'Pune',
      state: customer?.state || 'Maharashtra',
    },
  });

  const {
    register: regPass,
    handleSubmit: handlePassSubmit,
    reset: resetPass,
    formState: { errors: passErrors, isSubmitting: isPassSubmitting },
  } = useForm<PasswordData>({
    resolver: zodResolver(passwordSchema),
  });

  const onUpdateProfile = async (data: ProfileData) => {
    if (!customer) return;
    const updated = {
      ...customer,
      name: data.name,
      business: data.business || customer.business,
      email: data.email,
      contact: data.contact,
      city: data.city,
      state: data.state,
    };
    loginCustomer(updated, customerToken || 'token');
    setProfileSuccess(true);
    setTimeout(() => setProfileSuccess(false), 3000);
  };

  const onUpdatePassword = async (_data: PasswordData) => {
    setPasswordError('');
    await new Promise((r) => setTimeout(r, 600));
    setPasswordSuccess(true);
    resetPass();
    setTimeout(() => setPasswordSuccess(false), 3000);
  };

  return (
    <div className="space-y-6 max-w-4xl">
      <div>
        <h1 className="text-2xl font-bold text-slate-900">
          Account &amp; Entity Profile
        </h1>
        <p className="text-xs text-slate-500 mt-0.5">
          Manage your business contact details, authorized representatives, and authentication security.
        </p>
      </div>

      <div className="grid gap-6 md:grid-cols-12">
        {/* Profile Card */}
        <div className="md:col-span-7 space-y-6">
          <div className="bg-[#FFFDF9] rounded-3xl p-6 border border-[#EAE6DD] shadow-sm space-y-5">
            <div className="flex items-center gap-4 border-b border-[#EAE6DD] pb-5">
              <div className="relative">
                <div className="w-16 h-16 rounded-2xl bg-gradient-to-tr from-[#0084D1] to-[#7C3AED] text-white font-bold text-xl flex items-center justify-center shadow-md">
                  {customer?.name ? customer.name.slice(0, 2).toUpperCase() : 'CU'}
                </div>
                <button
                  type="button"
                  className="absolute -bottom-1 -right-1 p-1.5 rounded-lg bg-white border border-[#EAE6DD] shadow-sm text-slate-600 hover:text-[#0084D1]"
                >
                  <Camera className="w-3.5 h-3.5" />
                </button>
              </div>
              <div>
                <h3 className="font-bold text-base text-slate-900">{customer?.name}</h3>
                <p className="text-xs text-slate-500">{customer?.business || 'Business Entity'}</p>
                <span className="inline-block mt-1 text-[10px] font-extrabold uppercase px-2.5 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                  Verified Client Account
                </span>
              </div>
            </div>

            {profileSuccess && (
              <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-xs text-emerald-700 flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 shrink-0" />
                <span>Profile details updated successfully.</span>
              </div>
            )}

            <form onSubmit={handleProfileSubmit(onUpdateProfile)} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Full Name *
                </label>
                <input
                  {...regProfile('name')}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
                {profileErrors.name && <p className="mt-1 text-xs text-rose-500">{profileErrors.name.message}</p>}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Registered Business Name
                </label>
                <input
                  {...regProfile('business')}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
              </div>

              <div className="grid gap-3 sm:grid-cols-2">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Email Address *
                  </label>
                  <input
                    {...regProfile('email')}
                    type="email"
                    className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                  {profileErrors.email && <p className="mt-1 text-xs text-rose-500">{profileErrors.email.message}</p>}
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Contact Phone *
                  </label>
                  <input
                    {...regProfile('contact')}
                    className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                  {profileErrors.contact && <p className="mt-1 text-xs text-rose-500">{profileErrors.contact.message}</p>}
                </div>
              </div>

              <div className="grid gap-3 sm:grid-cols-2">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    City *
                  </label>
                  <input
                    {...regProfile('city')}
                    className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    State *
                  </label>
                  <input
                    {...regProfile('state')}
                    className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                </div>
              </div>

              <button
                type="submit"
                disabled={isProfileSubmitting}
                className="w-full py-3 rounded-xl btn-multicolor text-white font-bold text-xs shadow-sm flex items-center justify-center cursor-pointer disabled:opacity-60"
              >
                <span className="relative z-10">
                  {isProfileSubmitting ? 'Saving Changes...' : 'Save Profile Details'}
                </span>
              </button>
            </form>
          </div>
        </div>

        {/* Change Password Card */}
        <div className="md:col-span-5 space-y-6">
          <div className="bg-[#FFFDF9] rounded-3xl p-6 border border-[#EAE6DD] shadow-sm space-y-4">
            <div className="flex items-center gap-2">
              <KeyRound className="w-5 h-5 text-[#0084D1]" />
              <h3 className="font-bold text-base text-slate-900">Change Password</h3>
            </div>
            <p className="text-xs text-slate-500">Ensure your new password contains at least 6 characters.</p>

            {passwordSuccess && (
              <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-xs text-emerald-700 flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4 shrink-0" />
                <span>Password changed successfully.</span>
              </div>
            )}

            <form onSubmit={handlePassSubmit(onUpdatePassword)} className="space-y-3.5">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Current Password *
                </label>
                <input
                  type="password"
                  {...regPass('currentPassword')}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
                {passErrors.currentPassword && <p className="mt-1 text-xs text-rose-500">{passErrors.currentPassword.message}</p>}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  New Password *
                </label>
                <input
                  type="password"
                  {...regPass('newPassword')}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
                {passErrors.newPassword && <p className="mt-1 text-xs text-rose-500">{passErrors.newPassword.message}</p>}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Confirm New Password *
                </label>
                <input
                  type="password"
                  {...regPass('confirmPassword')}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
                {passErrors.confirmPassword && <p className="mt-1 text-xs text-rose-500">{passErrors.confirmPassword.message}</p>}
              </div>

              <button
                type="submit"
                disabled={isPassSubmitting}
                className="w-full py-3 rounded-xl btn-multicolor text-white font-bold text-xs shadow-sm flex items-center justify-center cursor-pointer disabled:opacity-60"
              >
                <span className="relative z-10">
                  {isPassSubmitting ? 'Updating...' : 'Update Password'}
                </span>
              </button>
            </form>
          </div>

          <div className="p-5 rounded-2xl bg-blue-50/50 border border-blue-100 text-xs text-slate-600 space-y-1">
            <p className="font-bold text-slate-900 flex items-center gap-1.5">
              <ShieldCheck className="w-4 h-4 text-[#0084D1]" /> Account Security Note
            </p>
            <p className="leading-relaxed">
              Your documents and PAN details are accessible only by your assigned CA team and verified operations staff.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  ShieldCheck,
  Lock,
  Mail,
  Phone,
  User,
  Building,
  ArrowRight,
  Search,
  Check,
  Sparkles,
  CheckCircle2,
  Loader2,
} from 'lucide-react';
import { services } from '@/lib/constants/services';
import { useAuthStore } from '@/store/auth-store';

const schema = z.object({
  name: z.string().min(1, 'Full name is required'),
  email: z.string().email('Valid email address is required'),
  mobile: z.string().min(10, '10-digit mobile number is required'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
  city: z.string().min(1, 'City is required'),
  service: z.string().min(1, 'Please choose an initial service of interest'),
});

type FormData = z.infer<typeof schema>;

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5001';

export default function ClientSignupPage() {
  const [serviceSearch, setServiceSearch] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const navigate = useNavigate();
  const { loginCustomer } = useAuthStore();

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      service: 'Private Limited Company Registration',
    },
  });

  const selectedService = watch('service');

  // Filter 250+ services via searchable type-ahead (2.1.3)
  const filteredServices = services
    .filter(
      (s) =>
        s.name.toLowerCase().includes(serviceSearch.toLowerCase()) ||
        s.category.toLowerCase().includes(serviceSearch.toLowerCase())
    )
    .slice(0, 20);

  const onSubmit = async (data: FormData) => {
    setStatus('loading');
    try {
      const res = await fetch(`${API_BASE}/v1/customer/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: data.name,
          email: data.email,
          mobile: data.mobile,
          password: data.password,
          city: data.city,
          service: data.service,
        }),
      });

      const json = await res.json();
      if (json?.success && json.customer && json.token) {
        loginCustomer(json.customer, json.token);
        setStatus('success');
        navigate('/portal');
      } else {
        setStatus('error');
      }
    } catch {
      setStatus('error');
    }
  };

  return (
    <div className="min-h-screen bg-[#FFFDF9] flex items-center justify-center p-4 sm:p-6 font-sans">
      <div className="w-full max-w-lg space-y-6">
        {/* Brand */}
        <div className="text-center space-y-2">
          <Link to="/" className="inline-flex items-center gap-2.5">
            <img src="/logo_black.png" alt="ETaxwala" className="h-10 w-auto" />
          </Link>
          <div>
            <span className="px-3 py-1 rounded-full bg-blue-50 text-[#0084D1] border border-blue-200 text-xs font-bold uppercase tracking-wider">
              Client Portal Account
            </span>
            <h1 className="text-2xl font-bold text-slate-900 mt-2">Create Your Client Account</h1>
            <p className="text-xs text-slate-500 max-w-sm mx-auto mt-1">
              Track compliance progress, upload KYC documents securely, and get dedicated Chartered
              Accountant support.
            </p>
          </div>
        </div>

        {/* Signup Form Card */}
        <div className="bg-white p-6 sm:p-8 rounded-3xl border border-[#EAE6DD] shadow-sm space-y-4">
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">Full Name *</label>
              <div className="relative">
                <User className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  {...register('name')}
                  placeholder="e.g. Rahul Sharma"
                  className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
              </div>
              {errors.name && <p className="mt-1 text-xs text-rose-500">{errors.name.message}</p>}
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Email Address *
                </label>
                <div className="relative">
                  <Mail className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    {...register('email')}
                    type="email"
                    placeholder="you@company.com"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                </div>
                {errors.email && (
                  <p className="mt-1 text-xs text-rose-500">{errors.email.message}</p>
                )}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Mobile Number *
                </label>
                <div className="relative">
                  <Phone className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    {...register('mobile')}
                    placeholder="10-digit phone"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                </div>
                {errors.mobile && (
                  <p className="mt-1 text-xs text-rose-500">{errors.mobile.message}</p>
                )}
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Create Password *
                </label>
                <div className="relative">
                  <Lock className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    {...register('password')}
                    type="password"
                    placeholder="Min 6 characters"
                    className="w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  />
                </div>
                {errors.password && (
                  <p className="mt-1 text-xs text-rose-500">{errors.password.message}</p>
                )}
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  City / State *
                </label>
                <input
                  {...register('city')}
                  placeholder="e.g. Pune, MH"
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                />
                {errors.city && <p className="mt-1 text-xs text-rose-500">{errors.city.message}</p>}
              </div>
            </div>

            {/* Searchable Service Autocomplete */}
            <div className="relative">
              <label className="block text-xs font-bold text-slate-700 mb-1">
                Select Service of Primary Interest *
              </label>
              <div
                onClick={() => setIsDropdownOpen(true)}
                className="w-full rounded-xl border border-slate-300 bg-white p-2.5 text-sm cursor-pointer flex items-center justify-between"
              >
                <span className="font-semibold text-slate-800 truncate">
                  {selectedService || 'Search from 250+ services...'}
                </span>
                <Search className="w-4 h-4 text-slate-400 shrink-0" />
              </div>

              {isDropdownOpen && (
                <div className="absolute z-50 mt-1 w-full rounded-2xl bg-white border border-[#EAE6DD] shadow-xl overflow-hidden p-2 space-y-2">
                  <div className="relative">
                    <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input
                      type="text"
                      autoFocus
                      placeholder="Type to search (e.g. GST, Pvt Ltd, Trademark)..."
                      value={serviceSearch}
                      onChange={(e) => setServiceSearch(e.target.value)}
                      className="w-full rounded-xl bg-slate-50 border border-slate-200 pl-9 pr-3 py-2 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                    />
                  </div>
                  <div className="max-h-48 overflow-y-auto space-y-1">
                    {filteredServices.map((s) => (
                      <button
                        type="button"
                        key={s.id}
                        onClick={() => {
                          setValue('service', s.name);
                          setIsDropdownOpen(false);
                          setServiceSearch('');
                        }}
                        className="w-full text-left px-3 py-2 rounded-xl text-xs hover:bg-blue-50 flex items-center justify-between text-slate-700 group cursor-pointer"
                      >
                        <span className="truncate group-hover:text-[#0084D1] font-medium">
                          {s.name}
                        </span>
                        <span className="text-[10px] text-slate-400 uppercase font-bold shrink-0 ml-2">
                          {s.category}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <button
              type="submit"
              disabled={status === 'loading'}
              className="w-full py-3.5 rounded-xl btn-multicolor text-white font-bold text-sm shadow-md flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 mt-2"
            >
              <span className="relative z-10 flex items-center justify-center gap-2">
                {status === 'loading' ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" /> Creating Account...
                  </>
                ) : (
                  <>
                    <span>Create Account &amp; Access Portal</span>{' '}
                    <ArrowRight className="w-4 h-4" />
                  </>
                )}
              </span>
            </button>
          </form>

          {/* Switch to Login */}
          <div className="pt-4 border-t border-[#EAE6DD] text-center text-xs text-slate-500">
            Already have an account?{' '}
            <Link to="/portal/login" className="text-[#0084D1] font-bold hover:underline">
              Sign In ΓåÆ
            </Link>
          </div>
        </div>

        {/* Security Assurance */}
        <div className="flex items-center justify-center gap-2 text-xs text-slate-400">
          <ShieldCheck className="w-4 h-4 text-emerald-600" />
          <span>256-Bit SSL Encrypted ΓÇó MCA / GST Compliant</span>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import {
  LifeBuoy,
  MessageSquare,
  Plus,
  Send,
  CheckCircle2,
  Clock,
  AlertCircle,
  Phone,
  Mail,
  X,
} from 'lucide-react';
import { playStaffMessageSentChime, playStaffChatChime } from '@/lib/staff-chat-audio';

export default function ClientSupportPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [ticketSubject, setTicketSubject] = useState('');
  const [ticketDesc, setTicketDesc] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const [tickets, setTickets] = useState<any[]>([]);

  React.useEffect(() => {
    fetch('/v1/customer/chat')
      .then((r) => r.json())
      .then((d) => {
        if (d?.success && Array.isArray(d.data)) {
          setMessages(
            d.data.map((m: any) => ({
              id: m.id,
              sender: m.sender,
              isStaff: m.role === 'staff',
              time: m.timestamp || 'Today',
              text: m.message,
            }))
          );
        }
      })
      .catch(() => {});

    fetch('/v1/customer/tickets')
      .then((r) => r.json())
      .then((d) => {
        if (d?.success && Array.isArray(d.data)) {
          setTickets(
            d.data.map((t: any) => ({
              id: t.id,
              subject: t.subject,
              category: 'Legal / CA Query',
              createdAt: t.date || 'Today',
              status: t.status === 'OPEN' ? 'In Progress' : 'Resolved',
            }))
          );
        }
      })
      .catch(() => {});
  }, []);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage.trim();
    setChatMessage('');
    playStaffMessageSentChime();

    setMessages((prev) => [
      ...prev,
      {
        id: Date.now(),
        sender: 'You',
        isStaff: false,
        time: 'Just now',
        text: userMsg,
      },
    ]);

    try {
      await fetch('/v1/customer/chat/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: userMsg }),
      });
    } catch {}
  };

  const handleCreateTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!ticketSubject.trim()) return;

    try {
      const res = await fetch('/v1/customer/tickets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ subject: ticketSubject, description: ticketDesc }),
      });
      const data = await res.json();
      if (data?.success && data.data) {
        setTickets((prev) => [
          {
            id: data.data.id,
            subject: data.data.subject,
            category: 'Legal / CA Query',
            createdAt: 'Today',
            status: 'In Progress',
          },
          ...prev,
        ]);
      }
    } catch {}
    setIsModalOpen(false);
    setTicketSubject('');
    setTicketDesc('');
  };

  return (
    <div className="space-y-6 max-w-6xl mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-display font-bold text-brand-navy">
              Support & CA Specialist Chat
            </h1>
            <span className="badge badge-gold">Direct CA Line</span>
          </div>
          <p className="text-xs text-slate-500 mt-1">
            Directly communicate with your assigned Chartered Accountant and track resolution
            tickets.
          </p>
        </div>

        <button onClick={() => setIsModalOpen(true)} className="btn btn-primary btn-sm">
          <Plus className="w-3.5 h-3.5" /> Raise New Ticket
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Live Chat with Specialist (2 Cols) */}
        <div className="lg:col-span-2 bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col h-[560px] overflow-hidden">
          <div className="p-4 bg-[#F7F8FA] border-b border-slate-200 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg bg-brand-navy text-white flex items-center justify-center font-bold text-xs">
                PK
              </div>
              <div>
                <h4 className="text-xs font-bold text-slate-800">
                  CA Pooja Kulkarni (Senior Case Specialist)
                </h4>
                <p className="text-[11px] text-emerald-700 font-semibold flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" /> Online
                  ΓÇó In-Charge
                </p>
              </div>
            </div>

            <div className="text-right text-xs">
              <a
                href="tel:+919123456789"
                className="font-bold text-brand-navy hover:underline inline-flex items-center gap-1"
              >
                <Phone className="w-3.5 h-3.5" /> Call Desk
              </a>
            </div>
          </div>

          {/* Chat Messages */}
          <div className="flex-1 p-4 overflow-y-auto space-y-3 bg-[#F7F8FA]/50">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex flex-col ${msg.isStaff ? 'items-start' : 'items-end'}`}
              >
                <span className="text-[10px] text-slate-400 font-medium mb-1 px-1">
                  {msg.sender} ΓÇó {msg.time}
                </span>
                <div
                  className={`max-w-[85%] sm:max-w-[70%] p-3.5 rounded-2xl text-xs leading-relaxed ${
                    msg.isStaff
                      ? 'bg-white text-slate-800 border border-slate-200 rounded-tl-none shadow-sm'
                      : 'bg-brand-navy text-white rounded-tr-none shadow-sm'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
          </div>

          {/* Send Input */}
          <form
            onSubmit={handleSendMessage}
            className="p-3 bg-white border-t border-slate-200 flex items-center gap-2"
          >
            <input
              type="text"
              value={chatMessage}
              onChange={(e) => setChatMessage(e.target.value)}
              placeholder="Type your message or question for CA Pooja..."
              className="input flex-1 text-xs"
            />
            <button type="submit" className="btn btn-primary btn-sm">
              <Send className="w-3.5 h-3.5" /> Send
            </button>
          </form>
        </div>

        {/* Tickets & Support Contact Info (1 Col) */}
        <div className="space-y-6">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-3">
            <h4 className="font-display font-bold text-sm text-slate-800">Support Tickets</h4>

            <div className="space-y-2.5">
              {tickets.map((tck) => (
                <div
                  key={tck.id}
                  className="p-3 rounded-xl bg-[#F7F8FA] border border-slate-200/80 space-y-1.5"
                >
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] font-mono font-bold text-brand-navy">
                      {tck.id}
                    </span>
                    <span className="badge badge-green text-[10px]">{tck.status}</span>
                  </div>
                  <p className="text-xs font-semibold text-slate-800">{tck.subject}</p>
                  <span className="text-[10px] text-slate-400 block">{tck.createdAt}</span>
                </div>
              ))}
            </div>
          </div>

          <div className="bg-[#FFFDF9] border border-[#EAE6DD] p-6 rounded-3xl space-y-3 shadow-xs relative overflow-hidden">
            <div className="h-0.5 w-10 bg-multicolor rounded-full" />
            <h4 className="font-bold text-sm text-slate-900">Central Grievance Helpline</h4>
            <p className="text-xs text-slate-600 leading-relaxed">
              If your assigned specialist is unavailable or you require urgent escalation:
            </p>
            <div className="pt-2 border-t border-[#EAE6DD] space-y-1.5 text-xs text-slate-700">
              <p className="font-semibold flex items-center gap-2">
                <span>≡ƒô₧</span> Toll-Free: 080-6902-9999
              </p>
              <p className="font-semibold flex items-center gap-2">
                <span>Γ£ë∩╕Å</span> support@etaxwala.com
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Ticket Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-[#FFFDF9] rounded-3xl p-6 sm:p-8 w-full max-w-lg shadow-xl border border-[#EAE6DD] space-y-4">
            <div className="flex items-center justify-between border-b border-[#EAE6DD] pb-3">
              <div>
                <h3 className="font-bold text-base text-slate-900">Create Support Ticket</h3>
                <p className="text-xs text-slate-500 mt-0.5">
                  Our central support &amp; compliance officers will respond within 4 hours
                </p>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                className="p-1 rounded-lg text-slate-400 hover:bg-slate-100 cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <form onSubmit={handleCreateTicket} className="space-y-3.5 text-xs">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Subject / Query Topic
                </label>
                <input
                  type="text"
                  placeholder="e.g. Need clarification regarding MOA clause"
                  value={ticketSubject}
                  onChange={(e) => setTicketSubject(e.target.value)}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Detailed Description
                </label>
                <textarea
                  rows={4}
                  placeholder="Describe your issue or question in detail..."
                  value={ticketDesc}
                  onChange={(e) => setTicketDesc(e.target.value)}
                  className="w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-xs focus:outline-none focus:ring-2 focus:ring-[#0084D1]/30"
                  required
                />
              </div>

              <div className="pt-3 border-t border-[#EAE6DD] flex justify-end gap-2">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="btn-outline-multicolor btn-sm cursor-pointer text-xs"
                >
                  Cancel
                </button>
                <button type="submit" className="btn-multicolor btn-sm cursor-pointer text-xs">
                  <span className="relative z-10">Submit Ticket</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

